let store=new Store(undefined,localStorage.getItem('wedding-clap-empty-active-company')||'default');const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let deliveryMigrationError='';try{store.persistDeliveryMigration()}catch(err){deliveryMigrationError=err.message;}
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v),date=v=>v?new Date(v+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not set';
const client=id=>store.data.clients.find(v=>v.id===id),event=id=>store.data.events.find(v=>v.id===id),person=id=>store.data.team.find(v=>v.id===id),initials=n=>n.split(' ').filter(x=>x!=='&').slice(0,2).map(x=>x[0]).join('');
const paths=['M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8','M21 11a8 8 0 0 1-8 8H5l-3 3V5h19z M6 7h11 M6 11h7','M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18','M3 7h18v14H3z M3 7V3h7l3 4','M3 5h18v15H3z M16 10h5 M7 10h4 M7 15h2','M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M5 22v-3a7 7 0 0 1 14 0v3','M9 5h12 M9 12h12 M9 19h12 M2 5l2 2 3-4 M2 12l2 2 3-4 M2 19l2 2 3-4','M4 21V10 M10 21V4 M16 21V13 M22 21H2','M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3'];
