let calBooking='All',calType='All',calTeam='All';
const nav=['Dashboard','Clients','Enquiries','Calendar','Projects','Finance','Team','Tasks','Reports','Settings'];let route='',search='',filter='All',calView='Month',calDate=today(),financeTab='Overview',clientTab='Overview',profileKey='';
const tag=s=>`<span class="tag ${esc(s?.toLowerCase())}">${esc(s)}</span>`,empty=(title,desc,action='')=>`<div class="empty"><h3>${title}</h3><p>${desc}</p>${action}</div>`,btn=(action,text,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function eventCard(e){const c=client(e.client);return `<div class="event-card" role="button" tabindex="0" data-event="${e.id}"><div class="date-tile"><strong>${e.date?e.date.slice(8):'—'}</strong><span>${e.date?new Date(e.date+'T12:00').toLocaleDateString('en',{month:'short'}):'TBC'}</span></div><div><h3>${esc(c?.name)} <span class="subtext">${esc(e.type)}</span></h3><p>${esc(e.venue)}${e.city?' · '+esc(e.city):''}</p><p>${e.timeNotRecorded?'Time not recorded':esc(e.start)+' – '+esc(e.end)} · ${e.team.length?e.team.map(t=>esc(person(t)?.name?.split(' ')[0])).join(', '):'Team unassigned'}</p></div><div class="event-side">${tag(e.status==='Shoot Completed'?'Completed':eventBooking(e))}${!e.date?tag('Date Not Fixed'):''}</div></div>`}
function taskRow(t){return `<div class="task-row"><input type="checkbox" aria-label="Complete ${esc(t.title)}" data-complete-task="${t.id}" ${t.status==='Completed'?'checked':''}><div><button class="small" data-action="edit:tasks:${t.id}">${esc(t.title)}</button><p>${date(t.due)} · ${esc(person(t.owner)?.name||'Unassigned')}</p></div>${tag(t.priority)}</div>`}
function stats(items){return `<div class="stats">${items.map(([l,v,f])=>`<div class="stat"><div class="label">${l}<span>◦</span></div><div class="value">${v}</div><div class="foot">${f}</div></div>`).join('')}</div>`}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtext">${sub}</p></div>${action}</div>`}
function dashboard(){const d=store.data,up=d.events.filter(e=>e.date>=today()&&e.status!=='Shoot Completed'&&activeEvent(e)).sort(sortEvents),td=up.filter(e=>e.date===today()),pending=d.clients.filter(c=>store.balance(c.id)>0),qs=d.enquiries.filter(q=>!q.client&&!['Lost','Canceled','Confirmed','Booked'].includes(q.status)&&q.followup&&q.followup<=today()).sort((a,b)=>a.followup.localeCompare(b.followup)),active=d.projects.filter(p=>!projectComplete(p)),ts=d.tasks.filter(t=>t.status!=='Completed').sort((a,b)=>a.due.localeCompare(b.due));return `<div class="home-heading"><div><p class="eyebrow">${new Date(today()+'T12:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short'})}</p><h1>Your studio, today.</h1></div><img class="home-logo" src="logo.png" alt="" width="1254" height="1254"></div><div class="home-summary"><span>${td.length} shoots today</span><span>${qs.length} follow-ups due</span><span>${ts.length} open tasks</span></div><div class="home-sections">${homeSection('Today',td.length,'#/calendar',td.map(eventCard).join('')||empty('No shoots today','Your next celebrations are below.'),'home-today')}${homeSection('Upcoming events',up.filter(e=>e.date>today()).length,'#/calendar',up.filter(e=>e.date>today()).slice(0,3).map(eventCard).join('')||empty('No upcoming events','Plan your next celebration.',btn('new:events','Add event','primary')))}${homeSection('Follow-ups',qs.length,'#/enquiries',qs.slice(0,3).map(q=>`<button class="action-row" data-action="edit:enquiries:${q.id}"><span><strong>${esc(q.name)}</strong><small>${date(q.followup)} · ${esc(q.status)}</small></span><span class="row-action">Follow up</span></button>`).join('')||empty('Follow-ups are clear','No conversations need attention today.'))}${homeSection('Pending tasks',ts.length,'#/tasks',ts.slice(0,3).map(taskRow).join('')||empty('All caught up','No pending tasks.'))}${homeSection('Pending payments',pending.length,'#/finance',pending.sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,3).map(c=>`<button class="action-row" data-action="new:payments:${c.id}"><span><strong>${esc(c.name)}</strong><small>${c.status==='Tentative'?'Tentative · ':''}Due ${date(c.due)}</small></span><span class="row-action money">${money(store.balance(c.id))}</span></button>`).join('')||empty('Payments up to date','No outstanding client balances.'))}${homeSection('Active projects',active.length,'#/projects',active.slice(0,3).map(p=>{const e=event(p.event);return `<a class="project-preview" href="#/projects"><div><strong>${esc(client(e?.client)?.name)}</strong><span>${stages[p.stage]}</span></div><div class="bar"><i style="width:${p.stage/9*100}%"></i></div><small>${esc(e?.type)} · Delivery ${date(p.due)}</small></a>`}).join('')||empty('No projects in production','Completed shoots start production automatically.'))}</div>`}
function render(){if(store.loadError){$('#app').innerHTML=`<main class="content"><h1>Saved data needs attention</h1><p class="subtext">Your saved data has been kept unchanged. Export it before restoring a backup or starting fresh.</p><div class="actions">${btn('raw-backup','Export saved data')}${btn('reset','Reset empty workspace')}${btn('empty','Start empty','danger')}</div><label class="linked">Import a valid backup<input type="file" id="import-backup" accept="application/json"></label></main>`;return;}const parts=location.hash.replace(/^#\//,'').split('/'),next=parts[0]||'dashboard',key=next+'/'+(parts[1]||'');if(route!==next){search='';filter='All'}if(profileKey!==key){clientTab='Overview';profileKey=key}route=next;const title=route==='delivery'?'Delivery':route==='more'?'More':route==='dashboard'?'Home':nav.find(n=>n.toLowerCase()===route)||'Home',primary=['dashboard','clients','calendar','tasks'],moreActive=!primary.includes(route);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#/dashboard"><img class="studio-logo" src="logo.png" alt="Wedding Clap logo" width="1254" height="1254"><strong>${esc(store.data.settings.company)}</strong></a><nav aria-label="Desktop navigation">${nav.map((n,i)=>`<a href="#/${n.toLowerCase()}" class="${n.toLowerCase()===route?'active':''}" ${n.toLowerCase()===route?'aria-current="page"':''}>${icon(i)}${n==='Dashboard'?'Home':n}</a>`).join('')}</nav><div class="sidebar-foot">Studio workspace<br>Saved on this browser</div></aside><main class="main"><header class="topbar"><a class="mobile-brand" href="#/dashboard"><img class="studio-logo" src="logo.png" alt="Wedding Clap logo" width="1254" height="1254"><strong>${esc(store.data.settings.company)}</strong></a><span class="crumb">${title}</span><div class="topbar-actions"><span class="subtext desktop-date">${date(today())}</span>${btn('quick','<span aria-hidden="true">＋</span><span>Quick Add</span>','primary top-quick')}</div></header><div class="content ${route==='clients'&&parts[1]?'profile-content':''}">${deliveryMigrationError?`<p role="alert">Delivery changes could not be saved: ${esc(deliveryMigrationError)}. Export a backup and free browser storage before reloading.</p>`:''}${route==='dashboard'?dashboard():page(route,parts[1])}<footer>Saved on this browser · Wedding Clap</footer></div></main><button class="quick-fab" data-action="quick" aria-label="Quick Add">＋</button><nav class="bottom-nav" aria-label="Main navigation">${[['dashboard','Home',0],['clients','Clients',1],['calendar','Calendar',3],['tasks','Tasks',7],['more','More',-1]].map(([r,label,i])=>`<a href="#/${r}" class="${r==='more'?moreActive?'active':'':route===r?'active':''}" ${(r==='more'?moreActive:route===r)?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('')}</nav></div>`;}
const tabs=(values,current,key)=>`<div class="tabs">${values.map(x=>`<button class="${current===x?'active':''}" data-${key}="${esc(x)}" aria-pressed="${current===x}">${esc(x)}</button>`).join('')}</div>`;
const toolbar=(placeholder,values=[])=>`<div class="toolbar"><input id="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(search)}">${values.length?tabs(values,filter,'filter'):''}</div>`;
const table=(headers,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('Nothing here yet','Add a record or adjust your filters.');
const match=(v)=>JSON.stringify(v).toLowerCase().includes(search.toLowerCase());
function page(r,id){switch(r){case 'clients':return id?clientDetail(id):clients();case 'enquiries':return enquiries();case 'calendar':return calendar();case 'delivery':return deliveryPage();case 'projects':return projects();case 'finance':return finance();case 'team':return team();case 'tasks':return tasks();case 'reports':return reports();case 'settings':return settings();case 'more':return more();default:return empty('Page not found','Return to the studio workspace.','<a class="linked" href="#/dashboard">Dashboard</a>')}}
function bookedClientEvents(id){return store.data.events.filter(e=>e.client===id&&['Confirmed'].includes(eventBooking(e))).sort(sortEvents)}
function clientEventDisplay(id){const es=bookedClientEvents(id);return es.length?es.map(e=>`<span class="booked-event-summary"><strong>${esc(e.type)}${es.filter(x=>x.type===e.type).length>1&&e.dayNumber?' · Day '+e.dayNumber:''}</strong><small>${e.date?date(e.date):'Date not fixed'}</small></span>`).join(''):'<span class="subtext">No booked events</span>'}

function clients(){const order=store.data.settings.clientOrder||[],rows=store.data.clients.slice().sort((a,b)=>(order.includes(a.id)?order.indexOf(a.id):9999)-(order.includes(b.id)?order.indexOf(b.id):9999)).filter(c=>clientSearchMatches(c,search)&&(filter==='All'||c.status===filter));return heading('Clients',`${rows.length} couples & stories`,`<div class="actions"><button data-reorder-toggle aria-pressed="${clientReorder}">${clientReorder?'Done':'Reorder'}</button>${btn('new:clients','＋ New client','primary')}</div>`)+clientSearchToolbar()+`<p class="reorder-hint" ${clientReorder?'':'hidden'}>Drag a handle to move a client. Use ↑ / ↓ keys when a handle is focused.</p><div class="client-list ${clientReorder?'reordering':''}">${rows.map(c=>{const next=store.data.events.filter(e=>e.client===c.id&&e.status!=='Shoot Completed'&&(e.date>=today()||!e.date)&&activeEvent(e)).sort(sortEvents)[0];return `<article class="client-sort-card" data-sort-client="${c.id}">${clientReorder?`<button class="client-drag-handle" data-drag-client="${c.id}" aria-label="Move ${esc(c.name)}" title="Drag to reorder">⠿</button>`:''}<a class="client-card" href="#/clients/${c.id}"><div class="client-card-head"><span class="initials">${esc(initials(c.name))}</span><span><small>${c.id}</small><h2>${esc(c.name)}</h2></span>${tag(c.status)}</div><div class="client-meta"><span><small>Booked events</small><span class="booked-event-list">${clientEventDisplay(c.id)}</span></span><span><small>Pending balance</small><strong class="money ${store.balance(c.id)>0?'balance':''}">${money(store.balance(c.id))}</strong></span></div><div class="next-event"><span>${icon(3)}</span><span>${next?`${esc(next.type)} · ${next.date?date(next.date):'Date not fixed'}<small>${next.timeNotRecorded?'Time not recorded':esc(next.start)}${next.city?' · '+esc(next.city):''}</small>`:'No upcoming event'}</span></div></a><div class="client-card-actions"><button class="small" data-action="edit:clients:${c.id}" aria-label="Edit ${esc(c.name)}">Edit Client</button></div></article>`}).join('')||empty('No clients found','Try a different search or add your first client.',btn('new:clients','New client','primary'))}</div>`}
function field(name,label,value='',type='text',options=null,extra=''){return `<div class="field ${name==='notes'?'wide':''}"><label for="f-${name}">${label}</label>${options?`<select id="f-${name}" name="${name}" ${extra}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`:type==='textarea'?`<textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea>`:type==='date'?`<div class="date-input-control"><input id="f-${name}" name="${name}" type="date" value="${esc(value)}" ${extra}><button type="button" class="date-picker-button" data-date-picker="f-${name}" aria-label="Open calendar for ${esc(label)}" ${/\bdisabled\b/.test(extra)?'disabled':''}><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18"/></svg></button></div>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</div>`}
const clientOptions=()=>store.data.clients.map(c=>[c.id,c.name]),teamOptions=()=>[['','Unassigned'],...store.data.team.map(t=>[t.id,t.name+' · '+t.role])];
function inlineField(table,id,name,label,value,type='text',options=null){return field(name,label,value,type,options,`data-inline="${table}:${id}:${name}"`).replaceAll(`f-${name}`,`f-${table}-${id}-${name}`)}
function clientDetail(id){const c=client(id);if(!c)return empty('Client not found','This client may have been deleted.','<a href="#/clients" class="linked">All clients</a>');const es=store.data.events.filter(e=>e.client===id).sort(sortEvents),ps=store.data.projects.filter(p=>es.some(e=>e.id===p.event)),phone=phoneNumber(c.phone),related=store.data.tasks.filter(t=>t.client===id||es.some(e=>e.id===t.event)||ps.some(p=>p.id===t.project));let body='';if(clientTab==='Overview')body=`<section class="panel"><h2>Booking at a glance</h2><div class="profile-money"><div><small>Booking amount</small><strong>${money(store.quote(c.id))}</strong></div><div><small>Received</small><strong>${money(store.paid(id))}</strong></div><div><small>Pending</small><strong>${money(store.balance(id))}</strong></div></div><div class="line-items"><span>${esc(bookingName(c.package))}</span><span>Due ${date(c.due)}</span></div></section><section class="panel inline"><h2>Client details</h2><p class="inline-hint">Edit here. Changes save when you leave a field.</p><div class="field-grid">${inlineField('clients',id,'phone','Phone',c.phone,'tel')}${inlineField('clients',id,'email','Email',c.email,'email')}${inlineField('clients',id,'address','Address',c.address)}${inlineField('clients',id,'bride','Bride name',c.bride||'')}${inlineField('clients',id,'groom','Groom name',c.groom||'')}${inlineField('clients',id,'leadSource','Lead source',c.leadSource||'Others','text',leadSources)}${inlineField('clients',id,'budget','Budget',c.budget||'Agreed','text',budgets)}</div><details class="edit-details"><summary>Edit booking details</summary><div class="field-grid">${inlineField('clients',id,'name','Couple / client name',c.name)}${inlineField('clients',id,'status','Booking status',c.status,'text',[...bookingStatuses,'Confirmed','Completed'])}${inlineField('clients',id,'date','Wedding date',store.weddingDate(id),'date')}${inlineField('clients',id,'due','Next payment due',c.due,'date')}${inlineField('clients',id,'price','Booking amount',c.price??c.amount,'number')}${inlineField('clients',id,'discount','Discount',c.discount||0,'number')}${inlineField('clients',id,'financeMode','Finance structure',c.financeMode||'Shared','text',[['Shared','One quotation for all days'],['Per day','Separate quotations per day']])}</div></details></section>${homeSection('Related tasks',related.length,'#/tasks',related.map(taskRow).join('')||'<p class="subtext">No client tasks yet.</p>')}${btn('new:tasks:'+id,'＋ Client task')}<section class="panel document-panel"><div class="panel-head"><h2>Documents</h2><label class="attach-button">Attach<input type="file" hidden data-document="${id}" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.txt"></label></div>${store.data.documents.filter(d=>d.client===id).map(d=>`<div class="document-row"><a class="linked" href="${esc(d.data)}" download="${esc(d.name)}">${esc(d.name)}</a>${btn('delete:documents:'+d.id,'Remove','small danger')}</div>`).join('')||'<p class="subtext">Contracts & references · Up to 1 MB each</p>'}</section><div class="profile-delete">${btn('delete:clients:'+id,'Delete client','danger')}</div>`;
if(clientTab==='Events')body=btn('new:packages:'+id,'＋ Group event prices','small')+`<div class="section-header"><h2>Celebrations <span class="count">${es.length}</span></h2>${btn('new:events:'+id,'＋ Add','small')}</div>${es.map(eventCard).join('')||empty('No events yet','Plan a celebration for this client.',btn('new:events:'+id,'Add event','primary'))}`;
if(clientTab==='Payments')body=clientPayments(c);
if(clientTab==='Team')body=assignmentList(es.map(e=>e.id),id);if(clientTab==='Delivery')body=deliveryGroups(store.data,id).map(deliveryGroupCard).join('')||empty('No events yet','Add an event to track delivery.');if(clientTab==='Project')body=ps.map(projectCard).join('')||empty('No production projects','Mark an event’s shoot complete to begin production.');
if(clientTab==='Notes')body=`<section class="panel inline"><h2>Client notes</h2><p class="inline-hint">Ideas, preferences & the details to remember.</p>${inlineField('clients',id,'notes','Notes',c.notes,'textarea')}${btn('save-note:'+id,'Save note','primary')}<p class="subtext note-save" aria-live="polite">Changes also save when you leave this field.</p></section>`;
return `<a class="back" href="#/clients">‹ Clients</a><div class="profile-heading"><span class="initials">${esc(initials(c.name))}</span><div><small>${c.id}</small><h1>${esc(c.name)}</h1><div class="booked-event-list profile-booked-events">${clientEventDisplay(c.id)}</div></div>${tag(c.status)}</div><div class="profile-actions">${btn('edit:clients:'+id,'Edit Client')}${phone?`<a href="tel:+${phone}" aria-label="Call ${esc(c.name)}">${contactIcon('call')}<span>Call</span></a><a href="https://wa.me/${phone}" target="_blank" rel="noopener" aria-label="WhatsApp ${esc(c.name)}">${contactIcon('chat')}<span>WhatsApp</span></a>`:`<button data-action="phone:${id}">${contactIcon('call')}<span>Call</span></button><button data-action="phone:${id}">${contactIcon('chat')}<span>WhatsApp</span></button>`}<button data-action="new:events:${id}">${icon(3)}<span>Add Event</span></button><button data-action="new:payments:${id}">${icon(5)}<span>Add Payment</span></button><button data-action="note:${id}">${contactIcon('note')}<span>Add Note</span></button></div>${tabs(['Overview','Events','Payments','Team','Delivery','Project','Notes'],clientTab,'client-tab')}<div class="profile-tab-body">${body}</div>`}
function enquiries(){const statuses=['New','Contacted','Follow-up',...bookingStatuses,'Confirmed'];return heading('Enquiries','Follow up thoughtfully. Turn conversations into celebrations.',btn('new:enquiries','＋ New enquiry','primary'))+toolbar('Search enquiries',['All',...statuses])+`<div class="cards">${store.data.enquiries.filter(q=>match(q)&&(filter==='All'||q.status===filter)).map(q=>`<article class="card"><div class="card-top"><div class="initials">${esc(initials(q.name))}</div>${tag(q.status)}</div><h2>${esc(q.name)}</h2><p>${date(q.date)} · ${esc(q.city)}<br>${esc(q.phone)}</p><p>${esc(q.notes)}</p><p class="subtext">${esc(q.leadSource||'Source not recorded')} · Budget ${esc(q.budget||'not recorded')}</p><div class="line-items"><span>${esc(q.package)}</span><strong>${money(q.amount)}</strong></div><div class="field" style="margin-top:16px"><label>Status</label><select data-inline="enquiries:${q.id}:status" ${q.client?'disabled':''}>${statuses.map(s=>`<option ${q.status===s?'selected':''}>${s}</option>`).join('')}</select></div><p>Follow-up · ${date(q.followup)}</p><div class="actions">${btn('edit:enquiries:'+q.id,'Edit details','small')}${q.client?`<a class="linked" href="#/clients/${q.client}">Open client</a>`:['Confirmed','Booked'].includes(q.status)?btn('convert:'+q.id,'Create client','primary small'):''}${btn('delete:enquiries:'+q.id,'Delete','danger small')}</div></article>`).join('')||empty('No enquiries here','Add an enquiry to begin the workflow.')}</div>`}
function calendar(){if(calView==='Week'&&innerWidth<1000)calView='Agenda';const d=new Date(calDate+'T12:00'),month=new Date(d.getFullYear(),d.getMonth(),1),start=new Date(month);start.setDate(1-(month.getDay()+6)%7);const events=store.data.events.filter(e=>activeEvent(e)&&(calBooking==='All'||(calBooking==='Date Not Fixed'?!e.date:eventBooking(e)===calBooking))&&(calType==='All'||e.type===calType)&&(calTeam==='All'||e.team.includes(calTeam))).sort(sortEvents),selected=events.filter(e=>e.date===calDate);let body='';if(calView==='Month'){const cells=Array.from({length:Math.ceil(((month.getDay()+6)%7+new Date(d.getFullYear(),d.getMonth()+1,0).getDate())/7)*7},(_,i)=>{const v=new Date(start);v.setDate(start.getDate()+i);const day=isoDate(v),es=events.filter(e=>e.date===day),confirmed=es.filter(e=>eventBooking(e)==='Confirmed').length,tentative=es.length-confirmed;return `<button class="month-day ${v.getMonth()!==d.getMonth()?'other':''} ${day===today()?'today':''} ${day===calDate?'selected':''}" data-select-date="${day}" aria-label="${date(day)} · ${es.length} ${es.length===1?'event':'events'}${tentative?' · '+tentative+' tentative':''}" aria-pressed="${day===calDate}"><span>${v.getDate()}</span><span class="date-markers">${confirmed?'<i class="confirmed-marker"></i>':''}${tentative?'<i class="tentative-marker"></i>':''}${es.length>1?`<small>${es.length}</small>`:''}</span></button>`}).join('');body=`<section class="month-panel"><div class="month-grid">${['M','T','W','T','F','S','S'].map((w,i)=>`<span class="weekday" aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}">${w}</span>`).join('')}${cells}</div></section><div class="legend"><span><i></i>Confirmed</span><span><i class="tentative"></i>Tentative</span><span>Unmarked = no matching events</span></div><section class="selected-events" aria-live="polite"><div class="section-header"><div><h2>${date(calDate)}</h2><p class="subtext">${selected.length} ${selected.length===1?'event':'events'}</p></div>${btn('new:events','＋ Event','small')}</div>${selected.map(eventCard).join('')||empty('No matching events','No events match this date and filters.',btn('new:events','Add event','primary'))}</section>`;}else if(calView==='Week'){const first=new Date(d);first.setDate(d.getDate()-(d.getDay()+6)%7);body='<div class="week-agenda">'+Array.from({length:7},(_,i)=>{const v=new Date(first);v.setDate(first.getDate()+i);const day=isoDate(v),es=events.filter(e=>e.date===day);return `<section class="agenda-group"><div class="agenda-date"><strong>${v.toLocaleDateString('en-IN',{weekday:'long'})}</strong><span>${date(day)}</span></div>${es.map(eventCard).join('')||'<p class="week-empty">Available · No events</p>'}</section>`}).join('')+'</div>';}else if(calView==='Agenda'){const upcoming=events.filter(e=>e.date>=calDate),days=[...new Set(upcoming.map(e=>e.date))];body=`<div class="agenda-start"><label for="agenda-start">From</label><input id="agenda-start" type="date" value="${calDate}" data-agenda-date></div><div class="agenda">${days.map(day=>`<section class="agenda-group"><div class="agenda-date"><strong>${day===today()?'Today':new Date(day+'T12:00').toLocaleDateString('en-IN',{weekday:'long'})}</strong><span>${date(day)} · ${upcoming.filter(e=>e.date===day).length} events</span></div>${upcoming.filter(e=>e.date===day).map(eventCard).join('')}</section>`).join('')||empty('No events from this date','Choose an earlier date or add a celebration.',btn('new:events','Add event','primary'))}</div>`;}else body=`<div class="agenda-start"><label for="day-date">Date</label><input id="day-date" type="date" value="${calDate}" data-agenda-date></div><div class="section-header"><h2>${new Date(calDate+'T12:00').toLocaleDateString('en-IN',{weekday:'long'})}</h2><span class="count">${selected.length} events</span></div>${selected.map(eventCard).join('')||empty('No matching events','No events match this date and filters.',btn('new:events','Add event','primary'))}`;
return heading('Calendar','Every celebration, one clear schedule.',btn('new:events','＋ Event','primary'))+`<div class="calendar-filters field-grid">${field('calBooking','Booking status',calBooking,'text',['All','Confirmed','Tentative','Date Not Fixed'])}${field('calType','Event type',calType,'text',['All',...new Set(store.data.events.map(e=>e.type))])}${field('calTeam','Team member',calTeam,'text',[['All','All team members'],...store.data.team.map(t=>[t.id,t.name])])}</div>`+tabs(innerWidth>=1000?['Month','Week','Agenda','Day']:['Month','Agenda','Day'],calView,'cal-view')+`<div class="calendar-controls"><button data-action="cal:prev" aria-label="Previous ${calView==='Month'?'month':['Agenda','Week'].includes(calView)?'week':'day'}">‹</button><h2>${calView==='Month'?d.toLocaleDateString('en-IN',{month:'long',year:'numeric'}):date(calDate)}</h2><button data-action="cal:next" aria-label="Next ${calView==='Month'?'month':['Agenda','Week'].includes(calView)?'week':'day'}">›</button>${btn('cal:today','Today','small')}</div>${body}${events.some(e=>!e.date)?`<section class="home-section"><h2>Dates not fixed</h2>${events.filter(e=>!e.date).map(eventCard).join('')}</section>`:''}`}
function projects(){const ps=store.data.projects.filter(p=>filter==='All'||(filter==='Active'?!projectComplete(p):projectComplete(p)));return heading('Projects','From completed shoot to final delivery.')+`<div class="toolbar">${tabs(['All','Active','Completed'],filter,'filter')}<span class="subtext">${ps.length} projects</span></div><div class="project-list">${ps.map(projectCard).join('')||empty('No projects here','Complete a shoot to start its production project.','<a class="linked" href="#/calendar">Open calendar</a>')}</div>`}
function paymentTable(ps,showClient=true){return `<div class="payment-list">${ps.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<article class="payment-card"><div class="payment-card-head"><span>${showClient?`<a href="#/clients/${p.client}"><strong>${esc(client(p.client)?.name)}</strong></a>`:`<strong>${esc(p.method)}</strong>`}<small>${p.date?date(p.date):'Date unknown'}${showClient?' · '+esc(p.method):''}</small></span><strong class="money">${money(p.amount)}</strong></div><p class="subtext">${esc(store.data.packages?.find(x=>x.id===p.package)?.name||'')} · ${esc(p.stage||'Other')} · ${p.event?esc(event(p.event)?.type||'Unlinked event'):'All events'}${p.transactionReference?' · Transaction '+esc(p.transactionReference):''}${p.reference?' · Original invoice '+esc(p.reference):''} · Invoice sent ${esc(p.invoice||'No')}</p>${p.notes?`<p class="subtext">${esc(p.notes)}</p>`:''}<div class="record-actions">${btn('edit:payments:'+p.id,'Edit','small')}${store.data.packageMigration?'':btn('delete:payments:'+p.id,'Delete','danger small')}</div></article>`).join('')||empty('No payments yet','Record a payment to update the client’s balance.')}</div>`}
function finance(){const d=store.data,booked=d.clients.reduce((s,c)=>s+store.quote(c.id),0),received=d.payments.reduce((s,p)=>s+Number(p.amount),0),spent=d.expenses.reduce((s,x)=>s+Number(x.amount),0);let body=financeTab==='Payments'?paymentTable(d.payments):financeTab==='Expenses'?`<div class="payment-list">${d.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<article class="payment-card"><div class="payment-card-head"><span><strong>${esc(x.title)}</strong><small>${date(x.date)} · ${esc(x.category)}</small></span><strong class="money">${money(x.amount)}</strong></div><p class="subtext">${esc(client(x.client)?.name||(x.sourceUnlinked?'Unlinked original client '+x.sourceClient:'Studio / general'))} · ${esc(event(x.event)?.type||'Unassigned day')}<br>${esc(x.vendor||'')} · ${esc(x.method||'Not set')}</p><div class="record-actions">${btn('edit:expenses:'+x.id,'Edit','small')}${btn('delete:expenses:'+x.id,'Delete','danger small')}</div></article>`).join('')||empty('No expenses yet','Record travel, team fees or studio costs.')}</div>`:`<div class="payment-list">${d.clients.map(c=>`<article class="payment-card"><div class="payment-card-head"><a href="#/clients/${c.id}"><strong>${esc(c.name)}</strong><small>${c.id} · ${esc(c.status)}</small></a><strong class="money">${money(store.balance(c.id))}</strong></div><div class="client-meta"><span><small>Booking amount</small>${money(store.quote(c.id))}</span><span><small>Received</small>${money(store.paid(c.id))}</span></div>${clientFinance(c)}<div class="payment-due"><span>Due ${date(c.due)}</span>${store.balance(c.id)>0?btn('new:payments:'+c.id,'Record payment','small primary'):tag('Paid in full')}</div></article>`).join('')||empty('No client balances','Add a client to begin tracking payments.')}</div>`;return heading('Finance','Balances, payments & studio expenses.',`<div class="actions">${btn('new:expenses','＋ Expense')}${btn('new:payments','＋ Payment','primary')}</div>`)+`<section class="finance-summary"><div><small>Outstanding</small><strong>${money(booked-received)}</strong></div><div><small>Received</small><strong>${money(received)}</strong></div><div><small>Expenses</small><strong>${money(spent)}</strong></div><p>Includes tentative bookings · Net receipts ${money(received-spent-d.assignments.reduce((n,a)=>n+a.paid,0))} · Team dues ${money(d.assignments.reduce((n,a)=>n+a.charge-a.paid,0))}</p></section><div class="toolbar">${tabs(['Overview','Payments','Expenses'],financeTab,'finance-tab')}${btn('export:finance','Export CSV','small')}</div>${body}`}
const expandedTeamMembers=new Set();
function team(){return heading('Team','Every assignment, every celebration. A clear picture for the crew.',`<div class="actions">${btn('new:assignments','Assign to event')}${btn('new:team','＋ Team member','primary')}</div>`)+toolbar('Search team members and roles')+`<div class="cards team-cards">${store.data.team.filter(match).map(t=>{const es=store.data.events.filter(e=>e.team.includes(t.id)&&e.status!=='Shoot Completed'&&activeEvent(e)&&(!e.date||e.date>=today())).sort((a,b)=>a.date.localeCompare(b.date)),open=expandedTeamMembers.has(t.id),panelId='team-details-'+encodeURIComponent(t.id),dues=store.data.assignments.filter(a=>a.member===t.id).reduce((n,a)=>n+a.charge-a.paid,0);return `<article class="card team-member-card ${open?'is-expanded':''}"><h2 class="team-member-heading"><button type="button" class="team-member-toggle" data-team-toggle="${esc(t.id)}" aria-expanded="${open}" aria-controls="${esc(panelId)}"><span class="initials" aria-hidden="true">${esc(initials(t.name))}</span><span class="team-member-identity"><span class="team-member-name">${esc(t.name)}</span><span class="subtext">${esc(t.role||'Team member')} · ${es.length} upcoming</span></span><svg class="team-member-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button></h2><div id="${esc(panelId)}" class="team-member-details" ${open?'':'inert'}><div class="team-member-details-inner"><div class="team-member-information"><p><strong>Role</strong><br>${esc(t.role||'Not recorded')}</p><p><strong>Phone</strong><br>${esc(t.phone||'Not recorded')}</p><div class="line-items"><span>Upcoming assignments</span><strong>${es.length}</strong></div><div class="line-items"><span>Team dues</span><strong>${money(dues)}</strong></div><h3>Upcoming events</h3>${es.map(e=>`<button class="team-upcoming-event" data-event="${esc(e.id)}"><strong>${esc(e.type)} · ${date(e.date)}</strong><span class="subtext">${esc(client(e.client)?.name)} · ${esc(e.city)}</span></button>`).join('')||'<p>No upcoming assignments.</p>'}<div class="actions team-member-actions">${btn('edit:team:'+t.id,'Edit','small')}${btn('delete:team:'+t.id,'Remove','small danger')}</div>${assignmentList(store.data.events.map(e=>e.id),'',t.id)}</div></div></div></article>`}).join('')||empty('Your crew starts here','Add photographers, editors and the rest of your team.')}</div>${assignmentList(store.data.events.map(e=>e.id))}`}
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-team-toggle]');if(!toggle)return;const id=toggle.dataset.teamToggle,open=toggle.getAttribute('aria-expanded')!=='true',card=toggle.closest('.team-member-card'),panel=document.getElementById(toggle.getAttribute('aria-controls'));toggle.setAttribute('aria-expanded',String(open));panel.inert=!open;card.classList.toggle('is-expanded',open);if(open)expandedTeamMembers.add(id);else expandedTeamMembers.delete(id);});
function tasks(){const ts=store.data.tasks.filter(t=>match(t)&&(filter==='All'||t.status===filter)).sort((a,b)=>a.due.localeCompare(b.due));return heading('Tasks',`${store.data.tasks.filter(t=>t.status!=='Completed').length} open tasks`,btn('new:tasks','＋ Task','primary'))+toolbar('Search tasks',['All','To do','In progress','Completed'])+`<div class="task-list">${ts.map(t=>`<article class="task-card ${t.status==='Completed'?'task-done':''}"><div class="task-main"><label class="task-check"><input type="checkbox" aria-label="Complete ${esc(t.title)}" data-complete-task="${t.id}" ${t.status==='Completed'?'checked':''}></label><div><h2>${esc(t.title)}</h2><p>${date(t.due)} · ${esc(person(t.owner)?.name||'Unassigned')}</p><div class="tags">${tag(t.priority)}${tag(t.status)}</div></div></div>${t.client||t.event||t.project?`<p class="task-context">${esc(client(t.client||event(t.event||store.data.projects.find(p=>p.id===t.project)?.event)?.client)?.name||'')} ${t.event?'· '+esc(event(t.event)?.type):t.project?'· Production project':''}</p>`:''}${t.notes?`<p class="subtext">${esc(t.notes)}</p>`:''}<div class="record-actions">${btn('edit:tasks:'+t.id,'Edit task','small')}${btn('delete:tasks:'+t.id,'Delete','small danger')}</div></article>`).join('')||empty('No tasks here','Adjust your filters or create a task.',btn('new:tasks','Create task','primary'))}</div>`}
function reports(){const d=store.data,rev=d.payments.reduce((s,p)=>s+p.amount,0),spent=d.expenses.reduce((s,x)=>s+x.amount,0),converted=d.enquiries.filter(q=>q.client).length;return heading('Reports','A live overview of bookings, cash flow and studio delivery.',btn('export:reports','Export report'))+stats([['Enquiry conversion',`${d.enquiries.length?Math.round(converted/d.enquiries.length*100):0}%`,`${converted} of ${d.enquiries.length} enquiries`],['Net receipts',money(rev-spent-d.assignments.reduce((n,a)=>n+a.paid,0)),'Payments less expenses and team payments'],['Shoot completion',`${d.events.length?Math.round(d.events.filter(e=>e.status==='Shoot Completed').length/d.events.length*100):0}%`,'Across all events'],['Projects delivered',d.projects.filter(p=>projectComplete(p)).length,`${d.projects.length} total projects`]])+`<div class="report-grid"><section class="panel"><h2>Enquiry pipeline</h2>${['New','Contacted','Follow-up',...bookingStatuses,'Confirmed'].map(s=>`<div class="line-items"><span>${s}</span><strong>${d.enquiries.filter(q=>q.status===s).length}</strong></div>`).join('')}</section><section class="panel"><h2>Production pipeline</h2>${stages.map((s,i)=>`<div class="line-items"><span>${s}</span><strong>${d.projects.filter(p=>p.stage===i).length}</strong></div>`).join('')}</section><section class="panel"><h2>Monthly receipts</h2>${d.payments.some(p=>!p.date)?`<div class="line-items"><span>Payment dates unknown</span><strong>${money(d.payments.filter(p=>!p.date).reduce((n,p)=>n+p.amount,0))}</strong></div>`:''}${[...new Set(d.payments.filter(p=>p.date).map(p=>p.date.slice(0,7)))].sort().map(m=>`<div class="line-items"><span>${new Date(m+'-01T12:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</span><strong>${money(d.payments.filter(p=>p.date.startsWith(m)).reduce((s,p)=>s+p.amount,0))}</strong></div>`).join('')||'<p class="subtext">No dated payments recorded.</p>'}</section><section class="panel"><h2>Team workload</h2>${d.team.map(t=>`<div class="line-items"><span>${esc(t.name)} · Due ${money(d.assignments.filter(a=>a.member===t.id).reduce((n,a)=>n+a.charge-a.paid,0))}</span><strong>${d.events.filter(e=>e.team.includes(t.id)&&e.status!=='Shoot Completed').length} assignments</strong></div>`).join('')}</section></div>`}
function settings(){return heading('Settings','Company preferences, invoice design & backups.')+companyWorkspacePanel()+brandingSettingsPanel()+(false?'<section class="panel"><h2>Original invoice records</h2><p class="subtext">Reconcile the four supplied invoices for Nitin, Keyur and Vandana. Matching records are retained and a backup is saved.</p><button type="button" data-import-original-invoices>Import shared invoices</button></section>':'')+ (store.data.packageMigration?'':`<section class="panel"><h2>Original invoice reconciliation</h2><p>Back up current data, link existing receipts and reconcile Keyur’s original invoices. Calendar dates are preserved.</p>${btn('migrate-packages','Reconcile original invoices','primary')}</section>`)+(store.storage.getItem(store.companyId==='default'?'wedding-clap-empty-before-packages-v1':store.storageKey+'-wedding-clap-empty-before-packages-v1')?btn('package-backup','Download pre-migration backup'):'')+`<section class="panel"><h2>Deleted clients</h2>${(store.data.deletedClients||[]).map(c=>`<div class="service-crew-row"><span>${esc(c.name)}</span>${btn('restore-client:'+c.id,'Restore','small')}</div>`).join('')||'<p class="subtext">No deleted clients.</p>'}</section>`+`<div class="detail-grid"><section class="panel"><h2>Studio</h2><form id="settings-form">${field('company','Company name',store.data.settings.company)}<p class="subtext">Currency · Indian rupee (INR)<br>Calendar timezone · Asia/Kolkata</p>${btn('save-settings','Save preferences','primary')}</form>${false?`<details><summary>Original record import notes</summary><p>7 clients · 16 event days · ₹2,60,000 quoted · ₹45,400 received · ₹2,14,600 pending.</p><p>Event times and most transaction dates are unknown. Two same-date Haldi records remain separate. Source quotation discrepancies are preserved.</p><p>Unlinked historical payments: WC-0004 ₹2,000; WC-0005 ₹7,000; WC-0006 ₹10,000. Held separately from active client balances.</p><p>Names with different casing are kept separately until identities are confirmed.</p></details>`:''}</section><div><section class="panel"><h2>Your prototype data</h2><p class="subtext">Changes are stored in this browser. Export a backup before moving devices or clearing browser data. Uploaded documents are included.</p><div class="actions">${btn('backup','Export backup')}${store.storage.getItem(store.companyId==='default'?'wedding-clap-empty-before-delivery-v1':store.storageKey+'-wedding-clap-empty-before-delivery-v1')?btn('delivery-backup','Before delivery cleanup backup'):''}${store.storage.getItem(store.companyId==='default'?'wedding-clap-empty-v1':store.storageKey+'-wedding-clap-empty-v1')?btn('previous-backup','Export previous browser data'):''}<label class="linked" style="padding:10px;cursor:pointer">Import backup<input type="file" accept="application/json" hidden id="import-backup"></label></div></section><section class="panel"><h2>A fresh start</h2><p class="subtext">Start again with an empty studio. This replaces the data in this copy only.</p><div class="actions">${btn('reset',store.companyId==='default'?'Reset empty workspace':'Reset company workspace')}${btn('empty','Start with empty data','danger')}</div></section><section class="panel"><h2>Prototype scope</h2><p class="subtext">No login or production backend. This workspace is for testing the full company workflow. Browser data is not shared between devices.</p></section></div></div>`}
function closeModal(){ $('#modal').close(); $('#modal').innerHTML='';document.body.classList.remove('sheet-open'); }
function modal(title,body,kind='form'){document.body.classList.add('sheet-open');$('#modal').className='sheet '+kind;$('#modal').setAttribute('aria-labelledby','modal-title');$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function quick(){modal('Quick Add',`<div class="quick-list">${[['enquiries','New enquiry','Start a conversation'],['clients','New client','Create a couple’s profile'],['events','New event','Plan a celebration'],['payments','Add payment','Update the balance'],['tasks','Create task','Keep things moving'],['expenses','Add expense','Track studio spending']].map(([t,l,s])=>`<button data-action="new:${t}"><span class="quick-icon">${icon(t==='events'?3:({enquiries:2,clients:1,payments:5,tasks:7,expenses:5}[t]))}</span><span class="quick-label">${l}<small>${s}</small></span></button>`).join('')}</div>`,'quick-sheet')}
function form(table,id='',context=''){if(table==='clients'&&!id)return newClientForm();if(table==='packages')return packageForm(id,context);if(table==='events'&&!id)return eventDaysForm(context);if(table==='assignments')return assignmentForm(id,context);if(table==='delivery')return deliveryForm(context);const row=id?store.data[table].find(v=>v.id===id):{},v=row||{};if(id&&!row)return toast('This record no longer exists');let html='',title='',selectedClient=context.startsWith('project=')?'':context;
if(['clients','enquiries'].includes(table)){title=table==='clients'?'client':'enquiry';html=field('name','Couple / client name',v.name||'','text',null,'required')+field('bride','Bride name',v.bride||'')+field('groom','Groom name',v.groom||'')+field('leadSource','Lead source',v.leadSource||'Instagram','text',leadSources)+field('budget','Budget',v.budget||'Agreed','text',budgets)+field('phone','Phone',v.phone||'','tel')+field('email','Email',v.email||'','email')+field('date','Wedding date',table==='clients'&&id?store.weddingDate(id):v.date||'','date')+(table==='clients'?field('address','Address',v.address||''):field('city','City',v.city||''))+`<input type="hidden" name="package" value="${esc(v.package||'Booking')}">`+field('price','Booking amount (₹)',v.price??v.amount??0,'number',null,'required min="0" step="1"')+field('discount','Discount (₹)',v.discount||0,'number',null,'required min="0" step="1"')+`<p class="wide subtext" id="quote-hint">Final quotation ${money(v.amount||0)}</p>`+(table==='clients'?field('financeMode','Finance structure',v.financeMode||'Shared','text',[['Shared','One quotation for all days'],['Per day','Separate quotations per day']]):'')+field('status','Status',v.status||(table==='clients'?'Booked':'New'),'text',table==='clients'?[...bookingStatuses,'Confirmed','Completed']:['New','Contacted','Follow-up',...bookingStatuses,'Confirmed'],v.client?'disabled':'')+field(table==='clients'?'due':'followup',table==='clients'?'Payment due':'Next follow-up',(table==='clients'&&id?v.due||'':v.due||v.followup||today()),'date')+field('notes','Notes',v.notes||'','textarea');}
if(table==='events'){title='event';if(!store.data.clients.length)return modal('Add a client first',`<p>Events belong to a client so their details stay connected.</p>${btn('new:clients','Create client','primary')}`);html=field('client','Client',v.client||selectedClient,'text',clientOptions(),'required disabled')+field('type','Event type',v.type||'Wedding','text',[...new Set(['Pre-Wedding','Engagement','Mehndi','Sangeet','Haldi','Wedding','Reception','Birthday','Maternity','Other',...(v.type?[v.type]:[])])])+field('date','Event date',v.date||'','date')+`<p class="wide subtext">Leave date blank if it is not fixed yet.</p>`+field('start','Start time',v.timeNotRecorded?'':v.start||'09:00','time',null,v.timeNotRecorded?'':'required')+field('end','End time',v.timeNotRecorded?'':v.end||'18:00','time',null,v.timeNotRecorded?'':'required')+field('venue','Event location',v.venue||'','text',null,'required')+servicePicker('services',v.services)+field('bookingStatus','Booking status',v.bookingStatus||client(v.client)?.status||'Booked','text',[...new Set([...bookingStatuses,'Confirmed','Completed',v.bookingStatus].filter(Boolean))])+field('price','Day booking amount (₹)',v.price||0,'number',null,'min="0" step="1"')+field('discount','Day discount (₹)',v.discount||0,'number',null,'min="0" step="1"')+`<p class="wide subtext" id="quote-hint">Day quotation ${money(v.quotation||0)}</p>`+field('city','City',v.city||'')+field('status','Shoot status',v.status||'Scheduled','text',['Not recorded','Scheduled','Shoot Completed'])+`<div class="wide">${id?serviceAssignmentRows(v):''}${(v.team||[]).map(member=>`<input type="hidden" name="team" value="${esc(member)}">`).join('')}</div>`+field('notes','Event notes',v.notes||'','textarea');}
if(table==='payments'){title='payment';if(!store.data.clients.length)return modal('Add a client first',btn('new:clients','Create client','primary'));html=paymentClientPicker(v.client||selectedClient)+paymentBookingField(v.client||selectedClient,v.package)+field('amount','Payment amount (₹)',v.amount||'','number',null,'required min="1" step="1"')+field('date','Payment date',v.sourceDateUnknown?'':v.date||today(),'date',null,v.sourceDateUnknown?'':'required')+field('event','Apply to event',v.event||'','text',[['','All client events'],...store.data.events.filter(e=>e.client===(v.client||selectedClient)).map(e=>[e.id,`${e.type} · ${date(e.date)}`])])+field('stage','Payment stage',v.stage||'Booking Amount','text',[...new Set([...corePaymentStages,...(v.stage?[v.stage]:[]),'Custom'])])+field('customStage','Custom stage name','','text',null,'data-custom-payment-stage')+field('transactionReference','Transaction reference',v.transactionReference||'','text',null,'placeholder="UPI / bank transaction ID (optional)"')+field('method','Method',v.method||'UPI','text',['Not set','UPI','Cash','Other','Bank transfer','Card','Cheque'])+(id?field('invoice','Previously sent invoice',v.invoice||'No','text',['No','Yes']):'<input type="hidden" name="invoice" value="No">')+field('notes','Payment notes',v.notes||'','textarea')+`<p id="payment-hint" class="note wide"></p>`;}
if(table==='expenses'){title='expense';html=field('title','Expense description',v.title||'','text',null,'required')+field('amount','Amount (₹)',v.amount||'','number',null,'required min="1" step="1"')+field('date','Date',v.sourceDateUnknown?'':v.date||today(),'date',null,v.sourceDateUnknown?'':'required')+field('category','Category',v.category||'Travelling','text',[...new Set([...expenseCategories,v.category].filter(Boolean))])+field('client','Related client',v.client||selectedClient,'text',[['','Studio / general'],...clientOptions()])+field('event','Related event',v.event||'','text',[['','Unassigned day'],...store.data.events.filter(e=>e.client===(v.client||selectedClient)).map(e=>[e.id,`${e.type} · ${date(e.date)}`])])+field('vendor','Vendor / payee',v.vendor||'')+field('method','Payment mode',v.method||'Not set','text',['Not set','UPI','Cash','Other','Bank transfer']);}
if(table==='team'){title='team member';html=field('name','Full name',v.name||'','text',null,'required')+field('role','Role',v.role||'Photographer','text',[...new Set([...services,'Semi Candid','Editor','Manager','Other','Photographer','Cinematographer','Drone Operator','Assistant','Album Designer',v.role].filter(Boolean))])+field('phone','Phone',v.phone||'','tel');}
if(table==='tasks'){title='task';let project=context.startsWith('project=')?context.slice(8):v.project||'';html=field('title','Task title',v.title||'','text',null,'required')+field('priority','Priority',v.priority||'Medium','text',['High','Medium','Low'])+field('due','Due date',v.due||today(),'date',null,'required')+field('status','Status',v.status||'To do','text',['To do','In progress','Completed'])+field('owner','Assigned to',v.owner||'','text',teamOptions())+field('client','Related client',v.client||selectedClient,'text',[['','None'],...clientOptions()])+field('event','Related event',v.event||'','text',[['','None'],...store.data.events.map(e=>[e.id,`${client(e.client)?.name} · ${e.type} · ${date(e.date)}`])])+field('project','Related project',project,'text',[['','None'],...store.data.projects.map(p=>[p.id,`${client(event(p.event)?.client)?.name} · ${event(p.event)?.type}`])])+field('notes','Notes',v.notes||'','textarea');}
if(table==='clients'&&!id){eventDayDrafts=[];html+=`<div class="wide"><h3>Day-wise event plan</h3>${field('days','Requirement of days',1,'text',Array.from({length:31},(_,i)=>i+1),'required').replaceAll('f-days','event-days-count')}<div id="event-day-fields"></div></div>`;}modal(`${id?'Edit':'New'} ${title}`,`<form id="record-form" data-table="${table}" data-id="${id}"><p class="form-error" role="alert"></p><div class="field-grid">${html}</div><div class="modal-footer">${btn('close','Cancel')}<button type="submit" class="primary">${id?'Save changes':'Add '+title}</button></div></form>`);if(table==='clients'&&!id)renderEventDays(1);if(table==='payments')syncCustomPaymentStage();if(table==='payments')$('#payment-client-search').setCustomValidity($('#f-client').value?'':'Select an existing client from the list');quoteHint();paymentHint();conflictHint();}
function paymentHint(){const f=$('#record-form');if(f?.dataset.table!=='payments')return;const id=f.elements.client.value;if(!id){$('#payment-hint').textContent='Select a client to see the outstanding balance';return;}const old=store.data.payments.find(p=>p.id===f.dataset.id),ev=event(f.elements.event.value),dayLimit=!store.packages(id).length&&ev&&client(id).financeMode==='Per day'?Number(ev.quotation||0)-store.eventPaid(ev.id)+(old?.event===ev.id?old.amount:0):null;$('#payment-hint').textContent=`Client balance: ${money(store.balance(id)+(old?.client===id?old.amount:0))}${f.elements.package?.value?' · Booking balance: '+money(store.packageBalance(f.elements.package.value)+(old?.package===f.elements.package.value?old.amount:0)):dayLimit!==null?' · Event balance: '+money(dayLimit):''}`}
function conflictHint(){const f=$('#record-form');if(f?.dataset.table!=='events'||!f.elements.date||!f.elements.date.value)return;const selected=[...f.querySelectorAll('[name="team"]:checked')].map(x=>x.value),dateValue=f.elements.date.value,from=f.elements.start.value,to=f.elements.end.value;const overlap=store.data.events.filter(e=>e.id!==f.dataset.id&&e.date===dateValue&&e.status!=='Shoot Completed'&&e.start<to&&e.end>from&&e.team.some(t=>selected.includes(t)));$('#conflict-hint').textContent=overlap.length?`Schedule overlap: ${overlap.map(e=>client(e.client)?.name+' · '+e.type).join('; ')}. Review the team assignment before saving.`:'';}
function eventDetail(id){const e=event(id);if(!e)return toast('Event not found');const c=client(e.client),p=store.data.projects.find(p=>p.event===id),booking=store.data.packages?.find(b=>b.events.includes(id));modal(esc(e.type),`<div class="event-sheet compact-event" data-event-context="${esc(id)}"><div class="event-overview"><a class="event-client" href="#/clients/${c?.id}" data-close-link><h2>${esc(c?.name||'Client')}</h2></a><div class="event-statuses"><span><small>Booking</small>${tag(eventBooking(e))}</span><span><small>Shoot</small>${tag(e.status)}</span></div></div><dl class="event-facts"><div><dt>Date</dt><dd>${e.date?date(e.date):'Date not fixed'}</dd><dd class="event-fact-secondary">${e.timeNotRecorded?'Time not recorded':esc(e.start)+' – '+esc(e.end)}</dd></div><div><dt>Location</dt><dd>${esc(e.venue||'Location not set')}</dd>${e.city?`<dd class="event-fact-secondary">${esc(e.city)}</dd>`:''}</div></dl>${serviceAssignmentRows(e)}<details class="compact-event-note" ${e.notes?'open':''}><summary>${e.notes?'Event note':'Add event note'}</summary>${inlineField('events',id,'notes','Event note',e.notes||'','textarea').replace('<textarea','<textarea aria-label="Event note"')}<small>Changes save when you leave the field.</small></details><details class="compact-event-extra"><summary>More details & actions</summary><details class="compact-event-extra"><summary>Team charges & details</summary>${assignmentList([id],c?.id)}${e.team.filter(member=>!store.data.assignments.some(a=>a.event===id&&a.member===member)).length?`<p class="subtext">Other crew: ${e.team.filter(member=>!store.data.assignments.some(a=>a.event===id&&a.member===member)).map(member=>esc(person(member)?.name||'Unassigned')).join(', ')}</p>`:''}</details><div class="actions">${booking?btn('edit:package-delivery:'+booking.id,'Delivery status','small'):''}${btn('delete:events:'+id,'Delete event','small danger')}</div></details><div class="compact-event-actions">${btn('edit:events:'+id,'Edit event','primary')}${e.status!=='Shoot Completed'?btn('complete-event:'+id,'Mark shoot completed'):p?'<a class="linked" href="#/projects" data-close-link>Open production</a>':''}</div></div>`,'event-detail');}

function confirmAction(title,description,action){modal(title,`<p>${description}</p><div class="modal-footer">${btn('close','Cancel')}${btn(action,'Continue','danger')}</div>`)}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csv(rows){return rows.map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function handleAction(a){const [op,table,id]=a.split(':');switch(op){case 'restore-client':store.restoreDeletedClient(table);render();toast('Client and linked records restored');break;case 'customize-stages':return customizeStages(table);case 'migrate-packages':store.migratePackages();render();toast('Packages migrated; original data backed up');break;case 'delivery-backup':download('wedding-clap-empty-before-delivery.json',store.storage.getItem(store.companyId==='default'?'wedding-clap-empty-before-delivery-v1':store.storageKey+'-wedding-clap-empty-before-delivery-v1')||'{}');break;case 'package-backup':download('wedding-clap-empty-before-packages.json',store.storage.getItem(store.companyId==='default'?'wedding-clap-empty-before-packages-v1':store.storageKey+'-wedding-clap-empty-before-packages-v1')||'{}');break;case 'invoice':return invoicePreview(table);case 'saved-invoice':return invoicePreview('',table);case 'invoice-settings':return invoiceSettings();case 'menu':$('.sidebar').classList.toggle('open');break;case 'close':closeModal();break;case 'quick':quick();break;case 'note':clientTab='Notes';render();requestAnimationFrame(()=>document.querySelector('[data-inline="clients:'+table+':notes"]')?.focus());break;case 'phone':clientTab='Overview';render();toast('Add a phone number in client details');break;case 'save-note':{const el=document.querySelector('[data-inline="clients:'+table+':notes"]');if(el){store.update('clients',table,{notes:el.value});toast('Note saved')}break;}case 'new':form(table,'',id||'');break;case 'edit':if(table==='delivery-items')return deliveryItemsForm(id);if(table==='package-delivery')return packageDeliveryForm(id);if(table==='delivery')deliveryForm(id);else form(table,id);break;case 'delete':confirmAction('Delete this record?',table==='clients'?'Move this client and their events, team assignments, pricing, payments, invoices, expenses, tasks and documents to Deleted clients? You can restore them from Settings.':table==='events'?'This event and its production project will be removed.':'This record will be removed from your browser data.',`remove:${table}:${id}`);break;case 'remove':try{if(table==='clients')store.deleteClientRecoverable(id);else store.remove(table,id)}catch(err){toast(err.message);return;}closeModal();if(table==='clients')location.hash='#/clients';render();toast('Record deleted');break;case 'convert':try{const c=store.convert(table);closeModal();location.hash='#/clients/'+c.id;toast('Client created. All enquiry details preserved.')}catch(e){toast(e.message)}break;case 'complete-event':store.update('events',table,{status:'Shoot Completed'});eventDetail(table);render();toast('Shoot completed. Production project created.');break;case 'advance':{const p=store.data.projects.find(p=>p.id===table);store.update('projects',table,{stage:Math.min(projectStages(p).length-1,p.stage+1)});render();toast('Project progress saved');break}case 'cal':{const d=new Date(calDate+'T12:00');if(table==='today')calDate=today();else{const sign=table==='prev'?-1:1;if(calView==='Month'){d.setDate(1);d.setMonth(d.getMonth()+sign)}else d.setDate(d.getDate()+sign*(['Agenda','Week'].includes(calView)?7:1));calDate=d.toLocaleDateString('en-CA')}render();break}case 'raw-backup':download('wedding-clap-empty-recovery.json',store.failedRaw||JSON.stringify(store.data));break;case 'previous-backup':{const old=store.storage.getItem(store.companyId==='default'?'wedding-clap-empty-v1':store.storageKey+'-wedding-clap-empty-v1');if(old)download('wedding-clap-empty-previous-browser-data.json',old);else toast('No previous browser data found');break;}case 'backup':download('wedding-clap-empty-backup.json',JSON.stringify(store.data,null,2));toast('Backup exported');break;case 'reset':case 'empty':confirmAction('Replace your current data?','Export a backup first if you want to keep your changes.',`do-${op}`);break;case 'do-reset':case 'do-empty':try{store.reset(op==='do-empty')}catch(err){toast(err.message);return;}closeModal();render();toast('Workspace reset');break;case 'export':if(table==='finance')download('wedding-clap-empty-finance.csv',csv([['Client ID','Client','Package amount','Received','Balance','Due'],...store.data.clients.map(c=>[c.id,c.name,store.quote(c.id),store.paid(c.id),store.balance(c.id),c.due])]),'text/csv');else download('wedding-clap-empty-report.csv',csv([['Metric','Value'],['Clients',store.data.clients.length],['Enquiries',store.data.enquiries.length],['Events',store.data.events.length],['Payments received',store.data.payments.reduce((s,p)=>s+p.amount,0)],['Expenses',store.data.expenses.reduce((s,x)=>s+x.amount,0)],['Projects completed',store.data.projects.filter(p=>projectComplete(p)).length]]),'text/csv');toast('Report exported');break;}}
function saveClientOrder(){const visible=[...document.querySelectorAll('[data-sort-client]')].map(el=>el.dataset.sortClient),saved=store.data.settings.clientOrder||[],all=store.data.clients.map(c=>c.id).sort((a,b)=>(saved.includes(a)?saved.indexOf(a):9999)-(saved.includes(b)?saved.indexOf(b):9999));let n=0;store.reorderClients(all.map(id=>visible.includes(id)?visible[n++]:id));}
document.addEventListener('click',e=>{if(e.target.closest('[data-reorder-toggle]')){clientReorder=!clientReorder;render();}if(clientReorder&&e.target.closest('.client-sort-card a'))e.preventDefault();},true);
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag-client]');if(!h||e.button!==0)return;e.preventDefault();h.setPointerCapture(e.pointerId);clientDrag={id:h.dataset.dragClient,pointer:e.pointerId,card:h.closest('[data-sort-client]')};clientDrag.card.classList.add('dragging');});
document.addEventListener('pointermove',e=>{if(!clientDrag||e.pointerId!==clientDrag.pointer)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-sort-client]');if(target&&target!==clientDrag.card){const r=target.getBoundingClientRect();target.parentNode.insertBefore(clientDrag.card,e.clientY>r.top+r.height/2?target.nextSibling:target);}if(e.clientY<110)window.scrollBy(0,-14);else if(e.clientY>innerHeight-110)window.scrollBy(0,14);});
document.addEventListener('pointerup',e=>{if(!clientDrag||e.pointerId!==clientDrag.pointer)return;clientDrag.card.classList.remove('dragging');clientDrag=null;try{saveClientOrder();toast('Client order saved')}catch(err){toast(err.message);render();}});
document.addEventListener('pointercancel',()=>{if(clientDrag){clientDrag=null;render();}});
document.addEventListener('keydown',e=>{const h=e.target.closest('[data-drag-client]');if(!h||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const card=h.closest('[data-sort-client]'),other=e.key==='ArrowUp'?card.previousElementSibling:card.nextElementSibling;if(!other)return;card.parentNode.insertBefore(card,e.key==='ArrowUp'?other:other.nextSibling);try{saveClientOrder();toast('Client order saved')}catch(err){toast(err.message);render();}});
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){if(action.closest('form')&&action.dataset.action==='save-settings')return;e.preventDefault();try{handleAction(action.dataset.action)}catch(err){toast(err.message);render();}return}const selectedDay=e.target.closest('[data-select-date]');if(selectedDay){calDate=selectedDay.dataset.selectDate;render();return}const ev=e.target.closest('[data-event]');if(ev)return eventDetail(ev.dataset.event);const c=e.target.closest('[data-client]');if(c){location.hash='#/clients/'+c.dataset.client;return}const stage=e.target.closest('[data-stage]');if(stage){const [id,n]=stage.dataset.stage.split(':');try{store.update('projects',id,{stage:Number(n)});render();toast('Project progress saved')}catch(err){toast(err.message);render()}return}for(const [attr,set] of [['filter',v=>filter=v],['calView',v=>calView=v],['financeTab',v=>financeTab=v],['clientTab',v=>clientTab=v]]){const el=e.target.closest(`[data-${attr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}]`);if(el){set(el.dataset[attr]);render();return}}if(e.target.closest('[data-close-link]'))closeModal()});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-event]')&&['Enter',' '].includes(e.key)){e.preventDefault();eventDetail(e.target.dataset.event)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const at=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(at,at)}if(e.target.closest('#record-form')){quoteHint();paymentHint();conflictHint()}});
document.addEventListener('change',async e=>{const el=e.target;if(el.closest('#assignment-form'))assignmentWarning();if(el.closest('#record-form'))quoteHint();if(['f-calBooking','f-calType','f-calTeam'].includes(el.id)){if(el.id==='f-calBooking')calBooking=el.value;if(el.id==='f-calType')calType=el.value;if(el.id==='f-calTeam')calTeam=el.value;render();return;}if(el.hasAttribute('data-date-unfixed')){const input=el.closest('[data-event-day]').querySelector('[data-day-field="date"]');input.disabled=el.checked;input.required=!el.checked;input.closest('.field').querySelector('[data-date-picker]').disabled=el.checked;return;}if(['event','package'].includes(el.name)&&el.closest('#record-form'))paymentHint();if(el.name==='client'&&el.closest('#record-form')&&['payments','expenses'].includes(el.closest('form').dataset.table)){refreshEventOptions(el.closest('form'));}if(el.id==='event-days-count'){captureEventDays();const n=Number(el.value);if(Number.isInteger(n)&&n>=1&&n<=31)renderEventDays(n);if(el.closest('#new-client-form')){capturePackagePlans();renderPackagePlans();}quoteHint();return;}if(el.hasAttribute('data-agenda-date')){calDate=el.value||today();render();return}if(el.dataset.inline){const [t,id,k]=el.dataset.inline.split(':');let v=el.value;if(k==='amount'){v=Number(v);if(!Number.isFinite(v)||v<store.paid(id)){toast('Package amount cannot be below payments received');render();return}}if(k==='name'&&!v.trim()){toast('A name is required');render();return}if(k==='email'&&v&&!el.checkValidity()){toast('Enter a valid email');render();return}try{if(['price','discount','financeMode'].includes(k)){store.reviseQuote(t,id,{[k]:k==='financeMode'?v:Number(v)})}else store.update(t,id,{[k]:v});}catch(err){toast(err.message);render();return;}if(!['notes','phone','email','address','owner','due'].includes(k))setTimeout(render,180);toast('Saved')}if(el.dataset.completeTask){try{store.update('tasks',el.dataset.completeTask,{status:el.checked?'Completed':'To do'});render();toast(el.checked?'Task completed':'Task reopened')}catch(err){toast(err.message);render()}}if(el.dataset.document){const f=el.files[0];if(!f)return;if(f.size>1024*1024)return toast('Please choose a document under 1 MB');let data;try{data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});}catch{toast('Could not read this file. Please choose it again.');return;}try{store.add('documents',{client:el.dataset.document,name:f.name,data});render();toast('Document attached')}catch{toast('Browser storage is full. Export a backup and remove old documents.')}}if(el.id==='import-backup'){try{const raw=JSON.parse(await el.files[0].text());validateBackup(raw);pendingBackup=raw;confirmAction('Import this backup?',`This replaces your current data with ${raw.clients.length} clients and ${raw.events.length} events.`,'import-confirm')}catch(err){toast('Invalid backup: '+err.message)}}});
let pendingBackup;
function validateBackup(d){return validateData(d);}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="import-confirm"]')&&pendingBackup){try{store.importData(pendingBackup);pendingBackup=null;closeModal();render();toast('Backup imported')}catch(err){toast(err.message)}}});
document.addEventListener('submit',e=>{if(e.target.id==='package-delivery-form'){e.preventDefault();const f=e.target;try{store.updatePackageDelivery(f.dataset.package,Object.fromEntries(new FormData(f)));closeModal();render();toast('Booking deliverables updated')}catch(err){f.querySelector('.form-error').textContent=err.message}return;}if(e.target.id==='assignment-form'){e.preventDefault();const f=e.target;try{store.assignment(Object.fromEntries(new FormData(f)),f.dataset.id);const returnEvent=f.dataset.returnEvent;closeModal();render();if(returnEvent)eventDetail(returnEvent);toast('Assignment and team dues saved')}catch(err){f.querySelector('.form-error').textContent=err.message}return;}if(e.target.id==='delivery-form'){e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));try{if(data.drive&&!/^https:\/\//i.test(data.drive))throw Error('Use a secure https link');store.update('events',f.dataset.deliveryEvent,{delivery:{...event(f.dataset.deliveryEvent)?.delivery,...data}});closeModal();render();toast('Delivery updated')}catch(err){f.querySelector('.form-error').textContent=err.message}return;}if(e.target.id==='settings-form'){e.preventDefault();try{store.setSettings({company:new FormData(e.target).get('company')});render();toast('Preferences saved')}catch(err){toast(err.message)}return}if(e.target.id==='event-days-form'){e.preventDefault();const f=e.target;try{captureEventDays();const n=Number(f.elements.days.value);if(!Number.isInteger(n)||n<1||n>31)throw Error('Enter 1 to 31 days');const clientId=f.elements.client.value;store.eventDays(clientId,eventDayDrafts.slice(0,n));closeModal();if(location.hash==='#/clients/'+clientId)clientTab='Events';render();toast(`${n} linked events created`)}catch(err){f.querySelector('.form-error').textContent=err.message}return;}if(e.target.id!=='record-form')return;e.preventDefault();const f=e.target,t=f.dataset.table,id=f.dataset.id,data=Object.fromEntries(new FormData(f));try{for(const key of ['name','title'])if(key in data){data[key]=data[key].trim();if(!data[key])throw Error('A name or title is required')}if('amount'in data){data.amount=Number(data.amount);if(!Number.isFinite(data.amount)||data.amount<0)throw Error('Enter a valid amount')}if(['clients','enquiries','events'].includes(t)){data.price=Number(data.price||0);data.discount=Number(data.discount||0);data.amount=finalQuote(data.price,data.discount);}if(t==='events'){data.client=store.data.events.find(e=>e.id===id)?.client;data.bookingOverride=data.bookingStatus!==client(data.client)?.status;data.services=new FormData(f).getAll('services').join(', ');if(!data.services&&!store.data.events.find(e=>e.id===id)?.sourceServicesUnknown)throw Error('Select required services');delete data.amount;data.quotation=finalQuote(data.price,data.discount);data.team=new FormData(f).getAll('team');data.timeNotRecorded=!data.start&&!data.end;if(!data.timeNotRecorded&&(!data.start||!data.end||data.end<=data.start))throw Error('Enter both times with end after start, or leave both blank if unknown.');}if(['payments','expenses'].includes(t)&&id)data.sourceDateUnknown=!data.date;if(t==='payments'){if(data.stage==='Custom'){data.stage=String(data.customStage||'').trim();if(!data.stage)throw Error('Enter a custom payment stage');}delete data.customStage;const old=store.data.payments.find(p=>p.id===id);if(id){const max=store.balance(data.client)+(old.client===data.client?old.amount:0);if(data.amount<=0||data.amount>max)throw Error('Enter a payment within the outstanding balance');store.editPayment(id,data)}else store.payment(data)}else if(id){if(t==='expenses'&&data.event&&!store.data.events.some(e=>e.id===data.event&&e.client===data.client))throw Error('Select an event belonging to this client');if(t==='clients'&&data.financeMode!=='Per day'&&data.amount<store.paid(id))throw Error('Package amount cannot be below payments received');if(['clients','events'].includes(t))store.reviseQuote(t,id,data);else store.update(t,id,data)}else if(t==='clients'){captureEventDays();const n=Number(f.elements.days.value);if(eventDayDrafts.length<n)throw Error('Complete every selected event day');delete data.days;for(const k of Object.keys(data))if(k.startsWith('day-'))delete data[k];const c=store.createClientPlan(data,eventDayDrafts.slice(0,n));location.hash='#/clients/'+c.id;}else{if(t==='expenses'&&data.event&&!store.data.events.some(e=>e.id===data.event&&e.client===data.client))throw Error('Select an event belonging to this client');const row=store.add(t,data);if(t==='events'&&data.status==='Shoot Completed')store.update(t,row.id,{status:'Shoot Completed'})}closeModal();if(route==='clients'&&location.hash.split('/')[2]===data.client){if(t==='payments')clientTab='Payments';if(t==='events')clientTab='Events';}render();toast('Saved. Connected views are up to date.')}catch(err){f.querySelector('.form-error').textContent=err.message}});
window.matchMedia('(min-width:1000px)').addEventListener('change',render);window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo({top:0,behavior:'instant'})});$('#modal').addEventListener('close',()=>document.body.classList.remove('sheet-open'));$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientY<r.top||e.clientY>r.bottom||e.clientX<r.left||e.clientX>r.right)closeModal()}});window.addEventListener('storage',e=>{if(e.key===store.storageKey&&e.newValue){try{store.data=validateData(JSON.parse(e.newValue));store.normalize();store.loadError='';}catch(err){store.failedRaw=e.newValue;store.loadError=err.message;}render()}});
if(!store.loadError&&document.modelContext?.registerTool){for(const tool of [{name:'read_studio_summary',description:'Read clients, events and outstanding balances from the studio.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({clients:store.data.clients.map(c=>({id:c.id,name:c.name,balance:store.balance(c.id)})),events:store.data.events})},{name:'start_quick_add',description:'Open the Quick Add menu to begin a new studio record.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:input=>{if(Object.keys(input).length)throw Error('No parameters expected');quick();return {opened:true}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
function projectCard(p){const e=event(p.event),c=client(e?.client),booking=store.data.packages?.find(b=>b.events.includes(p.event)),steps=projectStages(p),last=steps.length-1,done=completedProjectStages(p),count=steps.filter(s=>s!=='Completed'&&done.includes(s)).length,percent=Math.round(count/last*100);return `<section class="panel production-card"><div class="panel-head"><div><small>${esc(e?.type)} · ${date(e?.date)}</small><h2><a href="#/clients/${c?.id}">${esc(c?.name)}</a></h2></div>${tag(projectComplete(p)?'Completed':'In production')}</div><div class="production-current"><span>${count} / ${last} items done</span><strong>${percent}%</strong></div><div class="bar"><i style="width:${percent}%"></i></div><p class="subtext">${esc(person(p.owner)?.name||'Owner unassigned')} · Due ${date(p.due)}</p>${booking?`<p class="subtext">Booking: ${esc(bookingName(booking.name))}</p>${btn('edit:package-delivery:'+booking.id,'Deliverables','small')}`:''}<details class="production-details" open><summary>Stages & project details</summary>${btn('customize-stages:'+p.id,'Customize stages','small')}<p class="subtext">Tap any item to mark it done. Tap again to undo.</p><div class="project-steps">${steps.map((s,i)=>`<button class="step ${done.includes(s)?'done':''}" data-production-item="${p.id}:${i}" aria-pressed="${done.includes(s)}">${done.includes(s)?'✓ ':''}${esc(s)}</button>`).join('')}</div><div class="field-grid inline">${inlineField('projects',p.id,'owner','Production owner',p.owner,'text',teamOptions())}${inlineField('projects',p.id,'due','Delivery due',p.due,'date')}${inlineField('projects',p.id,'notes','Project notes',p.notes,'textarea')}</div>${btn('new:tasks:project='+p.id,'＋ Project task','small')}</details></section>`}
function icon(i){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${i===-1?'<circle cx="5" cy="12" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="19" cy="12" r="1.3"/>':`<path d="${paths[i]}"/>`}</svg>`}
function contactIcon(type){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${type==='call'?'M5 3h4l2 5-3 2a16 16 0 0 0 6 6l2-3 5 2v4a2 2 0 0 1-2 2C10 21 3 14 3 5a2 2 0 0 1 2-2':type==='chat'?'M21 11a9 9 0 0 1-9 9H7l-4 2 1-5a9 9 0 1 1 17-6 M8 8l2 3 3 2 3-2':'M4 4h10 M4 4v16h16V10 M12 15l8-8-3-3-8 8-1 4z'}"/></svg>`}
function phoneNumber(value){const n=String(value||'').replace(/\D/g,'');return n.length===10?'91'+n:n.length>=7&&n.length<=15?n:''}
function sortEvents(a,b){return (a.date+a.start).localeCompare(b.date+b.start)}
function isoDate(v){return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`}
function homeSection(title,count,href,body,cls=''){return `<section class="home-section ${cls}"><div class="section-header"><h2>${title} <span class="count">${count}</span></h2><a href="${href}">View all</a></div>${body}</section>`}
function more(){return heading('More','The rest of your studio, one tap away.')+`<div class="more-list">${[['Enquiries',2,'Conversations & follow-ups'],['Projects',4,'Production stages'],['Delivery',4,'Albums, films & raw data'],['Finance',5,'Payments & expenses'],['Team',6,'Your crew & assignments'],['Reports',8,'Studio performance'],['Settings',9,'Preferences & backups']].map(([name,i,desc])=>`<a href="#/${name.toLowerCase()}" class="more-item"><span class="more-icon">${icon(i)}</span><span><strong>${name}</strong><small>${desc}</small></span><span class="more-chevron" aria-hidden="true">›</span></a>`).join('')}</div>`}

const eventTypes=['Pre-Wedding','Engagement','Mehndi','Sangeet','Haldi','Wedding','Reception','Birthday','Maternity','Other'];
let eventDayDrafts=[];
function eventDaysForm(context=''){
 if(!store.data.clients.length)return modal('Add a client first',`<p>Events belong to a client.</p>${btn('new:clients','Create client','primary')}`);
 eventDayDrafts=[];
 modal('Plan event days',`<form id="event-days-form"><p class="form-error" role="alert"></p><div class="field-grid">${field('client','Client',context,'text',clientOptions(),'required')}${field('days','Requirement of days',1,'text',Array.from({length:31},(_,i)=>i+1),'required').replaceAll('f-days','event-days-count')}</div><p class="subtext">One linked event per day. Set each date separately. Events start with 9 am–6 pm; edit time and assign crew after saving.</p><div id="event-day-fields"></div><div class="modal-footer">${btn('close','Cancel')}<button class="primary" type="submit" id="save-event-days">Create 1 event</button></div></form>`);
 renderEventDays(1);
}
function captureEventDays(){document.querySelectorAll('[data-event-day]').forEach(section=>{const i=Number(section.dataset.eventDay),v=Object.fromEntries([...section.querySelectorAll('[data-day-field]:not([type="checkbox"])')].map(el=>[el.dataset.dayField,el.value]));v.services=[...section.querySelectorAll('[data-service]:checked')].map(el=>el.value).join(', ');v.dateNotFixed=section.querySelector('[data-date-unfixed]').checked;eventDayDrafts[i]=v;});}
function renderEventDays(n){
 $('#event-day-fields').innerHTML=Array.from({length:n},(_,i)=>{const d=new Date(calDate+'T12:00');d.setDate(d.getDate()+i);const v=eventDayDrafts[i]||{type:'Pre-Wedding',date:isoDate(d),venue:'',services:'',price:0,discount:0,bookingAmount:0};eventDayDrafts[i]=v;return `<section class="panel event-day-panel" data-event-day="${i}"><h3>Day ${i+1} · Event ${i+1}</h3><div class="field-grid">${[['type','Event type','text',eventTypes],['date','Event date','date',null],['venue','Event location','text',null],['price','Day booking amount (₹)','number',null],['discount','Day discount (₹)','number',null],['bookingAmount','Booking amount (₹)','number',null]].map(([k,l,t,o])=>field(`day-${i}-${k}`,l,v[k],t,o,`${k==='date'&&v.dateNotFixed?'disabled':'required'} ${t==='number'?'min="0" step="1"':''} data-day-field="${k}"`)).join('')}<label class="check-line wide"><input type="checkbox" data-date-unfixed ${v.dateNotFixed?'checked':''}>Date not fixed yet</label>${servicePicker('day-'+i+'-services',v.services,true)}<p class="wide subtext" data-day-quote>Final quotation ${money(Number(v.price||0)-Number(v.discount||0))}</p></div></section>`;}).join('');
 const button=$('#save-event-days');if(button)button.textContent=`Create ${n} ${n===1?'event':'events'}`;
}

function servicePicker(name,value,day=false){const selected=serviceList(value),options=[...new Set([...services,...selected])];return `<fieldset class="service-picker wide"><legend>Required services</legend><div class="service-options">${options.map((s,i)=>`<label><input type="checkbox" name="${name}" value="${esc(s)}" ${selected.includes(s)?'checked':''} ${day?'data-service':''}>${esc(s)}</label>`).join('')}</div></fieldset>`}
function quoteHint(){const f=$('#record-form');if(!f||!f.elements.price)return;try{let amount=finalQuote(f.elements.price.value,f.elements.discount.value);const existing=store.data[f.dataset.table]?.find(x=>x.id===f.dataset.id);if(existing?.sourceQuotationOverride&&Number(f.elements.price.value)===Number(existing.price)&&Number(f.elements.discount.value)===Number(existing.discount))amount=f.dataset.table==='events'?existing.quotation:existing.amount;if(f.dataset.table==='clients'&&$('#event-day-fields')){captureEventDays();const total=eventDayDrafts.slice(0,Number(f.elements.days.value)).reduce((n,d)=>n+finalQuote(d.price||0,d.discount||0),0);if(f.elements.financeMode.value==='Per day')amount=total;else if(!Number(f.elements.price.value)){const price=eventDayDrafts.slice(0,Number(f.elements.days.value)).reduce((n,d)=>n+Number(d.price||0),0),discount=Number(f.elements.discount.value)||eventDayDrafts.slice(0,Number(f.elements.days.value)).reduce((n,d)=>n+Number(d.discount||0),0);amount=finalQuote(price,discount);}}else if(f.dataset.table==='clients'&&f.elements.financeMode.value==='Per day')amount=store.quote(f.dataset.id);$('#quote-hint').textContent='Final quotation '+money(amount)}catch(err){$('#quote-hint').textContent=err.message}}
document.addEventListener('input',e=>{const panel=e.target.closest('[data-event-day]');if(panel){const price=panel.querySelector('[data-day-field="price"]').value,discount=panel.querySelector('[data-day-field="discount"]').value;try{panel.querySelector('[data-day-quote]').textContent='Final quotation '+money(finalQuote(price,discount))}catch(err){panel.querySelector('[data-day-quote]').textContent=err.message}}});
function eventBooking(e){return bookingState(e,client(e.client))}
function activeEvent(e){return !['Canceled','Lost'].includes(eventBooking(e))}
function paymentBookingField(clientId,selected=''){const rows=store.packages(clientId);return `<div id="payment-booking-field">${rows.length>1?field('package','Apply to booking / invoice',selected,'text',[['','Select booking / invoice'],...rows.map(p=>[p.id,p.name+(p.invoiceReference?' · '+p.invoiceReference:'')])]):`<input type="hidden" name="package" value="${esc(rows[0]?.id||'')}">`}</div>`;}
function refreshEventOptions(f){if(f.dataset.table==='payments'&&$('#payment-booking-field'))$('#payment-booking-field').outerHTML=paymentBookingField(f.elements.client.value);const select=f.elements.event;if(!select)return;select.innerHTML=`<option value="">${f.dataset.table==='payments'?'All client events':'Unassigned day'}</option>`+store.data.events.filter(e=>e.client===f.elements.client.value).map(e=>`<option value="${e.id}">${esc(e.type)} · ${date(e.date)}</option>`).join('');paymentHint();}

function packageCards(id){return `<section class="panel"><div class="section-header"><h2>Event pricing</h2>${btn('new:packages:'+id,'＋ Pricing group','small')}</div>${store.packages(id).map(p=>{const paid=store.packagePaid(p.id),balance=store.packageBalance(p.id);return `<article class="package-card"><h3>${esc(bookingName(p.name))}</h3><p class="subtext">${p.events.slice().sort((a,b)=>(event(a)?.date||'').localeCompare(event(b)?.date||'')).map(id=>esc(event(id)?.type)+' · '+date(event(id)?.date)).join('<br>')}</p><div class="line-items"><span>Original rate</span><strong>${money(p.price)}</strong></div><div class="line-items"><span>Discount</span><strong>${money(p.discount)}</strong></div><div class="line-items"><span>Final package</span><strong>${money(p.price-p.discount)}</strong></div><div class="line-items"><span>Received / Balance</span><strong>${money(paid)} / ${money(balance)}</strong></div>${tag(balance===0?'Paid':paid?'Partially Paid':'Unpaid')} ${p.invoiceReference?`<small>Original invoice ${esc(p.invoiceReference)}</small>`:''}<div class="actions">${btn('edit:packages:'+p.id,'Edit booking','small')}${btn('invoice:'+p.id,'Generate Invoice','small primary')}${(store.data.invoices||[]).filter(i=>i.package===p.id).map(i=>btn('saved-invoice:'+i.id,(i.documentKind==='receipt'?'Receipt ':i.documentKind==='stage-invoice'?'Stage invoice ':'Invoice ')+i.number,'small')).join('')}</div>${paymentTable(store.data.payments.filter(x=>x.package===p.id),false)}</article>`}).join('')}</section>`}
function packageForm(id='',clientId=''){const p=store.data.packages?.find(p=>p.id===id)||{},c=p.client||clientId;modal(id?'Edit booking':'Booking details',`<form id="package-form" data-id="${id}" data-client="${c}"><p class="form-error" role="alert"></p><div class="field-grid">${field('name','Booking description',p.name||'','text',null,'required')}${field('price','Original rate',p.price||0,'number',null,'min="0" required')}${field('discount','Discount',p.discount||0,'number',null,'min="0" required')}${field('billTo','Invoice billed to',p.billTo||'')}${p.id&&p.delivery?`<div class="wide"><p class="subtext">${p.delivery.items.length} delivery items. Edit descriptions and quantities in Delivery to retain progress.</p>${btn('edit:delivery-items:'+p.id,'Edit deliverables','small')}</div>`:field('deliverables','Deliverables (one per line)',(p.deliverables||[]).join('\n'),'textarea')+field('complimentary','Complimentary items (one per line)',(p.complimentary||[]).join('\n'),'textarea')}</div><h3>Select events for this price</h3><p class="subtext">Events already priced in another group are excluded.</p>${store.data.events.filter(e=>e.client===c&&!store.packages(c).some(group=>group.id!==id&&group.events.includes(e.id))).map(e=>`<label class="task-check"><input type="checkbox" name="events" value="${e.id}" ${p.events?.includes(e.id)?'checked':''}>${esc(e.type)} · ${date(e.date)}</label>`).join('')}<div class="modal-footer">${btn('close','Cancel')}<button class="primary" type="submit">Save pricing group</button></div></form>`)}
document.addEventListener('submit',e=>{if(e.target.id!=='package-form')return;e.preventDefault();const f=e.target,fd=new FormData(f);try{if(!fd.getAll('events').length)throw Error('Select at least one event for this price');store.savePackage({...Object.fromEntries(fd),client:f.dataset.client,events:fd.getAll('events'),deliverables:String(fd.has('deliverables')?fd.get('deliverables'):(store.data.packages?.find(p=>p.id===f.dataset.id)?.deliverables||[]).join('\n')).split('\n').map(x=>x.trim()).filter(Boolean),complimentary:String(fd.has('complimentary')?fd.get('complimentary'):(store.data.packages?.find(p=>p.id===f.dataset.id)?.complimentary||[]).join('\n')).split('\n').map(x=>x.trim()).filter(Boolean)},f.dataset.id);closeModal();render();toast('Package saved')}catch(err){f.querySelector('.form-error').textContent=err.message}});
function clientFinance(c){if(store.data.packageMigration&&!store.packages(c.id).length)return `<section class="panel"><p>Booking details are needed to link existing receipts.</p>${paymentTable(store.data.payments.filter(p=>p.client===c.id),false)}</section>`;if(store.packages(c.id).length)return packageCards(c.id);const es=store.data.events.filter(e=>e.client===c.id),cost=store.costs(c.id);return `<details class="finance-details"><summary>${c.financeMode==='Per day'?'Separate quotation per day':'One quotation for all days'} · Details</summary><div class="line-items"><span>Final quotation</span><strong>${money(store.quote(c.id))}</strong></div>${es.map(e=>`<div class="finance-day"><button class="small" data-event="${e.id}">${esc(e.type)} · ${date(e.date)}</button><p>${c.financeMode==='Per day'?`Quoted ${money(e.quotation||0)} · `:''}Paid ${money(store.eventPaid(e.id))}${c.financeMode==='Per day'?' · Due '+money(Number(e.quotation||0)-store.eventPaid(e.id)):''}</p></div>`).join('')}<div class="line-items"><span>Unallocated client payments</span><strong>${money(store.data.payments.filter(p=>p.client===c.id&&!p.event).reduce((n,p)=>n+p.amount,0))}</strong></div><div class="line-items"><span>Agreed team charges</span><strong>${money(cost.team)}</strong></div><div class="line-items"><span>Team paid / due</span><strong>${money(cost.teamPaid)} / ${money(cost.team-cost.teamPaid)}</strong></div><div class="line-items"><span>Other recorded expenses</span><strong>${money(cost.expenses)}</strong></div><div class="line-items"><span>Quotation less team charges & expenses</span><strong>${money(store.quote(c.id)-cost.team-cost.expenses)}</strong></div><p class="subtext">Team charges and expenses are tracked separately. Record a team charge once.</p></details>`}
function assignmentForm(id='',context='',selectedService=''){const returnEvent=$('#modal [data-event-context]')?.dataset.eventContext||($('#record-form')?.dataset.table==='events'?$('#record-form').dataset.id:'')||'',a=store.data.assignments.find(x=>x.id===id)||{},es=store.data.events.filter(e=>!context||e.id===context||e.client===context);if(!es.length)return modal('Add an event first','<p>Assignments belong to an event day.</p>');if(!store.data.team.length)return modal('Add your team first',btn('new:team','Add team member','primary'));const available=serviceList(event(a.event||es[0].id)?.services).filter(service=>!store.data.assignments.some(x=>x.event===(a.event||es[0].id)&&x.service===service&&x.id!==id));if(!id&&!available.length)return modal('All services assigned','<p>Each service already has a team member. Edit an existing assignment from Team.</p>');modal(id?'Edit assignment':'Assign team member',`<form id="assignment-form" data-id="${id}" data-return-event="${esc(returnEvent)}"><p class="form-error" role="alert"></p><input type="hidden" name="previousMember" value="${esc(a.member||'')}"><div class="field-grid">${field('event','Event day',a.event||es[0].id,'text',es.map(e=>[e.id,`${client(e.client)?.name} · ${e.type} · ${date(e.date)}`]),'required')}${field('service','Service provided',a.service||selectedService||serviceList(es[0].services)[0]||'Cinematic','text',[...new Set([...available,a.service].filter(Boolean))])}${field('member','Team member',a.member||'','text',assignmentMemberOptions(a.event||es[0].id,id,a.member),'required')}<details class="wide assignment-new-member"><summary>＋ Add new team member</summary><div class="field-grid">${field('newMemberName','Full name','','text')}${field('newMemberRole','Role',a.service||selectedService||'Cinematic','text',services)}${field('newMemberPhone','Phone','','tel')}</div><p class="subtext" data-new-member-error role="alert"></p><button type="button" data-create-assignment-member>Add member & select</button></details>${field('charge','Agreed charge (₹)',a.charge||0,'number',null,'required min="0" step="1"')}${field('paid','Amount paid (₹)',a.paid||0,'number',null,'required min="0" step="1"')}${field('method','Payment mode',a.method||'Not set','text',['Not set','UPI','Cash','Other','Bank transfer'])}</div><p class="subtext">Records a team payment already made; does not send money.</p><p class="subtext" id="assignment-overlap" aria-live="polite"></p><div class="modal-footer">${returnEvent?`<button type="button" data-return-service-event="${esc(returnEvent)}">Cancel</button>`:btn('close','Cancel')}<button class="primary" type="submit">Save assignment</button></div></form>`);refreshAssignmentMembers($('#assignment-form'),a.member);assignmentWarning()}
function assignmentList(ids,clientId='',memberId=''){const rows=store.data.assignments.filter(a=>ids.includes(a.event)&&(!memberId||a.member===memberId));return `<section class="panel assignment-section"><div class="section-header"><h3>Service assignments & dues</h3><div class="actions">${btn('new:team','＋ Add team member','small')}${btn('new:assignments:'+(ids.length===1?ids[0]:clientId),'＋ Assign','small')}</div></div>${rows.map(a=>`<article class="assignment-card"><div><strong>${esc(person(a.member)?.name||'Unassigned')}</strong>${tag(a.charge===0?'No charge':a.paid>=a.charge?'Paid':a.paid?'Partial':'Pending')}</div><p>${esc(event(a.event)?.type)} · ${esc(a.service)}</p><p>Charge ${money(a.charge)} · Paid ${money(a.paid)} · Due ${money(a.charge-a.paid)}</p><div class="record-actions">${btn('edit:assignments:'+a.id,'Edit','small')}${btn('delete:assignments:'+a.id,'Remove','small danger')}</div></article>`).join('')||'<p class="subtext">No service charges recorded. Existing crew assignments remain on each event.</p>'}</section>`}
function deliveryCard(e){const p=store.data.packages?.find(p=>p.events.includes(e.id));if(p)return `<section class="panel"><h3>Booking deliverables</h3><p>${esc(bookingName(p.name))}</p><p class="subtext">Deliverables are tracked once for this package. This event’s crew requirements remain separate.</p>${btn('edit:package-delivery:'+p.id,'Update package delivery','small')}</section>`;const {data:d,items,labels}=deliveryPlan(e),done=items.filter(k=>d[k]==='Yes').length,required=items.filter(k=>d[k]!=='Not required').length;return `<section class="panel delivery-card"><div class="section-header"><div><h3>${esc(e.type)} · ${date(e.date)}</h3><p class="subtext">${esc(client(e.client)?.name)} · ${done}/${required} delivered</p></div>${btn('edit:delivery:'+e.id,'Update','small')}</div><div class="delivery-grid">${items.map(k=>`<span><strong>${esc(labels[k]||k)}</strong>${tag(d[k]==='Yes'?'Delivered':d[k]==='Not required'?'Not required':d[k]==='No'?'Pending':'Not set')}</span>`).join('')}</div>${d.brideChanges?`<p class="subtext">Bride album changes: ${esc(d.brideChanges)}</p>`:''}${d.groomChanges?`<p class="subtext">Groom album changes: ${esc(d.groomChanges)}</p>`:''}${d.drive&&/^https:\/\//i.test(d.drive)?`<a class="linked" href="${esc(d.drive)}" target="_blank" rel="noopener">Open delivery folder</a>`:''}</section>`}
function deliveryForm(id){const p=store.data.packages?.find(p=>p.events.includes(id));if(p)return packageDeliveryForm(p.id);const e=event(id);if(!e)return toast('Event not found');const {data:d,items,labels}=deliveryPlan(e);modal('Update delivery',`<form id="delivery-form" data-delivery-event="${id}"><p class="form-error" role="alert"></p><h3>${esc(client(e.client)?.name)} · ${esc(e.type)}</h3><div class="field-grid">${field('requirements','Deliverables (one per line)',d.requirements||'','textarea')}${items.map(k=>field(k,labels[k]||k,d[k]||'Not set','text',[['Not set','Not set'],['No','Pending'],['Yes','Delivered'],['Not required','Not required']])).join('')}${items.includes('Bride Album')?field('brideChanges','Bride album changes',d.brideChanges||'','textarea'):''}${items.includes('Groom Album')?field('groomChanges','Groom album changes',d.groomChanges||'','textarea'):''}${field('drive','Google Drive / delivery link',d.drive||'','url')}</div><div class="modal-footer">${btn('close','Cancel')}<button type="submit" class="primary">Save delivery</button></div></form>`)}
function deliveryGroupCard(group){return group.kind==='package'?packageDeliveryCard(group.record):deliveryCard(group.record)}
function packageDeliveryCard(p){const items=p.delivery?.items||[],required=items.filter(i=>i.status!=='Not required'),done=required.filter(i=>i.status==='Yes').length;return `<section class="panel delivery-card" data-delivery-package="${esc(p.id)}"><div class="section-header"><div><h3>${esc(bookingName(p.name))}</h3><p class="subtext">${esc(client(p.client)?.name)} · ${items.length?done+'/'+required.length+' delivered':'Deliverables not configured'}</p></div><div class="actions">${btn('edit:package-delivery:'+p.id,'Update status','small')}${btn('edit:delivery-items:'+p.id,'Edit deliverables','small')}</div></div><p class="subtext">Booking · ${p.events.slice().sort((a,b)=>(event(a)?.date||'').localeCompare(event(b)?.date||'')).map(id=>esc(event(id)?.type)+' · '+date(event(id)?.date)).join('<br>')}</p>${['deliverable','complimentary'].map(kind=>{const rows=items.filter(i=>i.kind===kind);return rows.length?`<h4>${kind==='complimentary'?'Complimentary items':'Deliverables'}</h4><div class="delivery-grid">${rows.map(i=>`<span><strong>${esc(itemText(i))}</strong>${tag(i.status==='Yes'?'Delivered':i.status==='No'?'Pending':i.status==='Partial'?'Partially delivered':i.status==='In progress'?'In progress':i.status==='Not required'?'Not required':'Not set')}${i.quantity?`<small>${i.deliveredQuantity||0} / ${i.quantity} delivered</small>`:''}${i.deliveredDate?`<small>Delivered ${date(i.deliveredDate)}</small>`:''}${i.notes?`<small>${esc(i.notes)}</small>`:''}${i.needsReview?'<small>Previous event progress needs review</small>':''}</span>`).join('')}</div>`:''}).join('')}${!items.length?'<p class="subtext">Deliverables not configured. Add the agreed items using Edit deliverables.</p>':''}${p.delivery?.drive&&/^https:\/\//i.test(p.delivery.drive)?`<a class="linked" href="${esc(p.delivery.drive)}" target="_blank" rel="noopener">Open delivery folder</a>`:''}</section>`}
function packageDeliveryForm(id){const p=store.data.packages?.find(p=>p.id===id);if(!p)return toast('Package not found');modal('Update delivery status',`<form id="package-delivery-form" data-package="${esc(id)}"><p class="form-error" role="alert"></p><h3>${esc(client(p.client)?.name)} · ${esc(p.client)}</h3><p>${esc(bookingName(p.name))}</p><p class="subtext">One checklist shared across ${p.events.length} event dates.</p>${(p.delivery?.items||[]).map(i=>`<section class="panel"><strong>${esc(itemText(i))}</strong><div class="field-grid">${field(i.id,'Status: '+i.label,i.status,'text',[['Not set','Not set'],['No','Pending'],['In progress','In progress'],['Partial','Partially delivered'],['Yes','Delivered'],['Not required','Not required']])}${i.quantity?field(i.id+'-delivered','Delivered quantity: '+i.label,i.deliveredQuantity||0,'number',null,`min="0" max="${i.quantity}"`):'<p class="subtext">For partial delivery, set a required quantity in Edit deliverables.</p>'}<details class="wide"><summary>Date & notes</summary><div class="field-grid">${field(i.id+'-date','Delivered date: '+i.label,i.deliveredDate||'','date')}${field(i.id+'-notes','Notes: '+i.label,i.notes||'','textarea')}</div></details>${i.needsReview?`<label class="check-line"><input type="checkbox" name="resolve-${esc(i.id)}">I checked the previous records and confirm this item’s status.</label>`:''}</div></section>`).join('')}${field('drive','Google Drive / delivery link',p.delivery?.drive||'','url')}<div class="modal-footer">${btn('close','Cancel')}<button type="submit" class="primary">Save delivery</button></div></form>`)}
let deliveryItemDrafts=[];
function deliveryItemsForm(id){const p=store.data.packages?.find(p=>p.id===id);if(!p)return;deliveryItemDrafts=structuredClone(p.delivery?.items||[]);modal('Edit deliverables',`<form id="delivery-items-form" data-package="${esc(id)}"><p class="form-error" role="alert"></p><h3>${esc(client(p.client)?.name)} · ${esc(p.client)}</h3><p>${esc(bookingName(p.name))}</p><p class="subtext">Changes update Delivery and future invoice drafts. Prices and saved invoices stay unchanged.</p><div id="delivery-item-rows"></div><button type="button" data-add-delivery-item>＋ Add item</button><div class="modal-footer">${btn('close','Cancel')}<button class="primary" type="submit">Save deliverables</button></div></form>`);renderDeliveryItemRows();}
function captureDeliveryItems(){document.querySelectorAll('[data-delivery-item-row]').forEach(row=>{const i=Number(row.dataset.deliveryItemRow);deliveryItemDrafts[i]={...deliveryItemDrafts[i],...Object.fromEntries([...row.querySelectorAll('[data-item-field]')].map(el=>[el.dataset.itemField,el.value]))};});}
function renderDeliveryItemRows(){const target=$('#delivery-item-rows');target.innerHTML=deliveryItemDrafts.map((i,n)=>`<section class="panel" data-delivery-item-row="${n}"><div class="section-header"><h4>Item ${n+1}</h4><button class="small" type="button" data-remove-delivery-item="${n}">Remove item</button></div><div class="field-grid">${field('item-'+n+'-label','Description '+(n+1),i.label,'text',null,'required data-item-field="label"')}${field('item-'+n+'-quantity','Required quantity '+(n+1),i.quantity??'','number',null,'min="1" step="1" data-item-field="quantity"')}${field('item-'+n+'-duration','Duration / specification '+(n+1),i.duration||'','text',null,'data-item-field="duration"')}${field('item-'+n+'-kind','Item type '+(n+1),i.kind||'deliverable','text',[['deliverable','Package deliverable'],['complimentary','Complimentary item']],'data-item-field="kind"')}</div></section>`).join('')||'<p class="subtext">Deliverables not configured. Add an item to begin.</p>';}
const deliveryTemplates={pre:['2 cinematic reels (30–60 seconds each)','40–50 selected edited images','5 countdown images','All raw photos'],wedding:['Unlimited raw photos','Cinematic teaser (1 minute) and highlight (3–5 minutes)','Traditional full-length video (1–3 hours) per day','1 photobook (250 selected photos)','2 cinematic reels']};
let packagePlanDrafts=[];
function newClientForm(){eventDayDrafts=[];packagePlanDrafts=[];modal('New client',`<form id="new-client-form" class="compact-client-form"><p class="form-error" role="alert"></p><div class="field-grid">${field('name','Client / couple name','','text',null,'required')}${field('phone','Phone','','tel')}${field('status','Status','Booked','text',bookingStatuses)}${field('days','Event days',1,'text',Array.from({length:31},(_,i)=>i+1),'required').replaceAll('f-days','event-days-count')}</div><details class="compact-details"><summary>Names & optional details</summary><div class="field-grid">${field('nameMode','Auto-fill names','manual','text',[['manual','Enter names manually'],['fromClient','Bride & groom from client name'],['fromCouple','Client name from bride & groom']])}${field('bride','Bride name','')}${field('groom','Groom name','')}${field('email','Email','','email')}${field('address','Address','')}${field('leadSource','Lead source','Instagram','text',leadSources)}${field('budget','Budget','Agreed','text',budgets)}</div><input type="checkbox" name="useCoupleNames" value="on" hidden><input type="checkbox" name="useClientName" value="on" hidden><p class="subtext" id="couple-name-hint" hidden></p></details><input type="hidden" name="due" value=""><input type="hidden" name="notes" value=""><h3>Events</h3><div id="event-day-fields"></div><h3>Price & payment</h3>${field('packageCount','Pricing groups',1,'text',Array.from({length:31},(_,i)=>i+1))}<p class="subtext">Use one group for a combined price, or multiple groups for separate prices.</p><div id="new-package-plans"></div><p id="new-client-summary" class="subtext"></p><div class="modal-footer">${btn('close','Cancel')}<button type="submit" class="primary">Review & add client</button></div></form>`);renderEventDays(1);renderPackagePlans();}

function capturePackagePlans(){document.querySelectorAll('[data-package-plan]').forEach(row=>{const i=Number(row.dataset.packagePlan);packagePlanDrafts[i]={...packagePlanDrafts[i],...Object.fromEntries([...row.querySelectorAll('[data-plan-field]')].map(el=>[el.dataset.planField,el.value]))};});}
function renderPackagePlans(){const f=$('#new-client-form');if(!f)return;const n=Number(f.elements.days.value),count=Math.min(n,Number(f.elements.packageCount.value)||1);f.elements.packageCount.value=String(count);for(const option of f.elements.packageCount.options)option.disabled=Number(option.value)>n;for(const row of f.querySelectorAll('[data-event-day]')){for(const key of ['price','discount','bookingAmount']){const el=row.querySelector('[data-day-field="'+key+'"]');el.required=false;el.disabled=true;el.closest('.field').hidden=true;}row.querySelector('[data-day-quote]').hidden=true;}$('#new-package-plans').innerHTML=Array.from({length:count},(_,i)=>{const p=packagePlanDrafts[i]||{name:count===1?'Booking':'Group '+(i+1),price:0,discount:0,bookingAmount:0,paymentDate:today(),method:'UPI',deliverables:'',complimentary:''};packagePlanDrafts[i]=p;return `<section class="panel" data-package-plan="${i}"><h4>${count>1?'Pricing group '+(i+1):'Booking price'}</h4><fieldset class="pricing-event-picker"><legend>Events in this group</legend>${Array.from({length:n},(_,j)=>{const owner=Number(f.dataset['dayPackage'+j]??-1),assigned=owner===-1?-1:Math.min(owner,count-1);return `<label><input type="checkbox" data-pricing-event="${j}" data-pricing-group="${i}" ${assigned===i?'checked':''} ${assigned>=0&&assigned!==i?'disabled':''}>${esc(eventDayDrafts[j]?.type||'Event')} · Day ${j+1}</label>`;}).join('')}</fieldset><div class="field-grid"><input type="hidden" name="plan-${i}-name" data-plan-field="name" value="${count>1?'Pricing Group '+(i+1):'Booking'}">${[['price','Package price (₹)','number'],['discount','Discount (₹)','number'],['bookingAmount','Booking payment received (₹)','number'],['paymentDate','Actual payment date','date'],['method','Payment method','text']].map(([k,l,t])=>field('plan-'+i+'-'+k,l,p[k],t,k==='method'?['UPI','Cash','Bank transfer','Other']:null,`data-plan-field="${k}" ${['price','discount'].includes(k)?'required':''} ${t==='number'?'min="0"':''}`)).join('')}<input type="hidden" data-plan-field="deliverables" value="${esc(p.deliverables)}"><input type="hidden" data-plan-field="complimentary" value="${esc(p.complimentary)}"></div><p class="subtext" data-group-total></p></section>`;}).join('')+Array.from({length:n},(_,i)=>{const owner=Number(f.dataset['dayPackage'+i]??-1);return `<input type="hidden" name="day-package-${i}" value="${owner===-1?-1:Math.min(owner,count-1)}">`;}).join('')+`<p class="final-price" id="new-client-final-price" aria-live="polite"></p>`;syncNewClientPaymentFields();updateNewClientFinalPrice();syncPricingEventAvailability(f);}

let pendingNewClient=null;
document.addEventListener('click',e=>{if(e.target.closest('[data-add-delivery-item]')){captureDeliveryItems();deliveryItemDrafts.push({label:'',kind:'deliverable',quantity:null});renderDeliveryItemRows();}const remove=e.target.closest('[data-remove-delivery-item]');if(remove){captureDeliveryItems();deliveryItemDrafts.splice(Number(remove.dataset.removeDeliveryItem),1);renderDeliveryItemRows();}});
document.addEventListener('change',e=>{const el=e.target,f=el.closest('#new-client-form');if(!f)return;if(el.name==='packageCount'){capturePackagePlans();renderPackagePlans();}if(el.hasAttribute('data-day-package'))f.dataset['dayPackage'+el.dataset.dayPackage]=el.value;if(el.hasAttribute('data-plan-template')){capturePackagePlans();const i=Number(el.dataset.planTemplate),p=packagePlanDrafts[i];if(el.value.startsWith('copy:')){const source=store.data.packages.find(p=>p.id===el.value.slice(5));p.deliverables=packageDeliverables(source).join('\n');p.complimentary=packageDeliverables(source,'complimentary').join('\n');}else{p.deliverables=(deliveryTemplates[el.value]||[]).join('\n');p.complimentary=el.value==='wedding'?'1 minibook\n1 digital invitation\n1 pendrive':'';}const row=el.closest('[data-package-plan]');row.querySelector('[data-plan-field="deliverables"]').value=p.deliverables;row.querySelector('[data-plan-field="complimentary"]').value=p.complimentary;}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='delivery-items-form'){e.preventDefault();captureDeliveryItems();try{store.saveDeliveryItems(f.dataset.package,deliveryItemDrafts);closeModal();render();toast('Deliverables updated. Future invoice drafts use this list.')}catch(err){f.querySelector('.form-error').textContent=err.message}return;}if(f.id==='new-client-form'){e.preventDefault();try{captureEventDays();capturePackagePlans();const fd=new FormData(f);if(fd.get('status')==='Quote Sent')packagePlanDrafts.forEach(p=>{p.bookingAmount=0;p.paymentDate='';});const days=eventDayDrafts.slice(0,Number(fd.get('days'))),plans=packagePlanDrafts.slice(0,Number(fd.get('packageCount'))).map((p,i)=>({...p,dayIndexes:days.map((d,j)=>Number(fd.get('day-package-'+j))===i?j:-1).filter(j=>j>=0),deliverables:p.deliverables.split('\n').map(x=>x.trim()).filter(Boolean),complimentary:p.complimentary.split('\n').map(x=>x.trim()).filter(Boolean)}));if(!String(fd.get('name')).trim())throw Error('Enter a client name');if(days.some((d,j)=>Number(fd.get('day-package-'+j))<0))throw Error('Select a pricing group for every event');for(const p of plans){finalQuote(p.price,p.discount);if(!p.dayIndexes.length)throw Error('Link at least one event to each package');}pendingNewClient={value:Object.fromEntries(['name','bride','groom','phone','email','address','leadSource','budget','status','due','notes','days','packageCount','useCoupleNames','useClientName','nameMode'].map(k=>[k,fd.get(k)])),days,plans};modal('Review client booking',`<h3>${esc(fd.get('name'))}</h3><p>${days.length} event dates · ${plans.length} pricing ${plans.length===1?'group':'groups'}</p>${plans.map(p=>`<section class="panel"><h4>${esc(bookingName(p.name))} · ${money(finalQuote(p.price,p.discount))}</h4><p>${p.dayIndexes.map(i=>esc(days[i].type)+' · '+(days[i].dateNotFixed?'Date not fixed':date(days[i].date))).join('<br>')}</p><p>Booking receipt: ${money(p.bookingAmount||0)}</p><p>${p.deliverables.length?p.deliverables.map(esc).join('<br>'):''}</p>${p.complimentary.length?'<h4>Complimentary</h4>'+p.complimentary.map(esc).join('<br>'):''}</section>`).join('')}<div class="modal-footer"><button data-new-client-back>Back to edit</button><button class="primary" data-confirm-new-client>Add client</button></div><p id="new-client-review-error" role="alert"></p>`);}catch(err){f.querySelector('.form-error').textContent=err.message}return;}});
document.addEventListener('click',e=>{if(e.target.closest('[data-confirm-new-client]')){try{const {value,days,plans}=pendingNewClient,c=store.createPackagedClient(value,days,plans);pendingNewClient=null;closeModal();location.hash='#/clients/'+c.id;render();toast('Client, booking and deliverables created together.')}catch(err){$('#new-client-review-error').textContent=err.message;}}if(e.target.closest('[data-new-client-back]')){const saved=pendingNewClient;newClientForm();const f=$('#new-client-form');for(const [k,v] of Object.entries(saved.value))if(f.elements[k]){if(f.elements[k].type==='checkbox')f.elements[k].checked=v==='on';else f.elements[k].value=v;}syncClientName();syncBrideGroomNames();eventDayDrafts=saved.days;packagePlanDrafts=saved.plans.map(p=>({...p,deliverables:p.deliverables.join('\n'),complimentary:p.complimentary.join('\n')}));saved.plans.forEach((p,i)=>p.dayIndexes.forEach(j=>f.dataset['dayPackage'+j]=String(i)));renderEventDays(saved.days.length);renderPackagePlans();}});

function deliveryPage(){return heading('Delivery','Albums, films and files — one checklist per booking.')+toolbar('Search client or event')+`<div class="delivery-list">${deliveryGroups(store.data).filter(g=>match({...g.record,clientName:client(g.record.client)?.name,eventNames:g.kind==='package'?g.record.events.map(id=>event(id)?.type).join(' '):''})).map(deliveryGroupCard).join('')||empty('No delivery records','Add a client or event to start tracking deliverables.')}</div>`}

render();

function assignmentWarning(){const f=$('#assignment-form');if(!f)return;const e=event(f.elements.event.value),member=f.elements.member.value,overlap=e?.date?store.data.events.filter(x=>x.id!==e.id&&x.date===e.date&&x.status!=='Shoot Completed'&&activeEvent(x)&&x.start<e.end&&x.end>e.start&&x.team.includes(member)):[];$('#assignment-overlap').textContent=overlap.length?'Schedule overlap: '+overlap.map(x=>client(x.client)?.name+' · '+x.type).join('; ')+'. Review before saving.':''}
let currentInvoiceDraft=null;
function draftDeliverables(d){const p=store.data.packages.find(p=>p.id===d.package);d.deliverables=packageDeliverables(p);d.complimentary=packageDeliverables(p,'complimentary');}
function originalInvoiceMarkup(d){if(d.documentKind)return paymentDocumentMarkup(d);return `<article class="invoice-preview"><header><div><h2>${esc(d.company.company)}</h2><p>Invoice ${d.number?'#'+esc(d.number):'Draft — number assigned on save'}</p><strong>Balance Due ${money(d.balance)}</strong></div><img src="logo.png" alt="Wedding Clap logo"></header><p>${esc(d.company.address).replaceAll('\n','<br>')}<br>${esc(d.company.phone)}<br>${esc(d.company.email)}</p><div class="invoice-parties"><p><strong>Bill To</strong><br>${esc(d.billTo)}</p><p>Invoice date: ${date(d.date)}<br>Terms: ${esc(d.termsLabel)}</p></div><section><h3>Item & Description</h3><h3>${esc(d.packageName)}</h3><p>Qty 1 · Rate ${money(d.price)} · Discount ${money(d.discount)} · Amount ${money(d.total)}</p>${d.events.map(e=>`<p><strong>${esc(e.type)} · ${e.date?date(e.date):'Date not fixed'}</strong><br>${esc([e.venue,e.city].filter(Boolean).join(' · '))}<br>${esc(e.services||'Requirements not recorded')}</p>`).join('')}<h3>Deliverables</h3>${d.deliverables.map(x=>`<p>• ${esc(x)}</p>`).join('')||'<p>Enter deliverables in Edit booking before saving.</p>'}${d.complimentary.length?'<h3>Complimentary</h3>'+d.complimentary.map(x=>`<p>• ${esc(x)}</p>`).join(''):''}</section><section><h3>Previous payments</h3>${d.payments.map(p=>`<div class="line-items"><span>${esc(p.stage)} · ${date(p.date)} · ${esc(p.method)}</span><strong>−${money(p.amount)}</strong></div>`).join('')||'<p>No payments received</p>'}<div class="line-items"><span>Subtotal / Total / Balance Due</span><strong>${money(d.balance)}</strong></div><p>Total in words: ${esc(amountWords(d.balance))}</p></section><section><h3>Notes</h3><p>${esc(d.notes).replaceAll('\n','<br>')}</p><h3>Terms & Conditions</h3><p>${esc(d.terms).replaceAll('\n','<br>')}</p><p class="signature">${esc(d.company.signatory)}<br>${esc(d.company.company)}<br><small>Authorized signatory</small></p></section></article>`}
function invoicePreview(packageId='',savedId='',customizationKey='',documentDraft=null){const saved=(store.data.invoices||[]).find(i=>i.id===savedId);currentInvoiceDraft=saved?structuredClone(saved):(documentDraft||invoiceDraft(store,packageId));if(saved?.documentKind)return paymentDocumentPreview(saved.paymentId,saved.documentKind,saved.id);if(!saved&&!currentInvoiceDraft.clientInvoice)draftDeliverables(currentInvoiceDraft);const d=currentInvoiceDraft;if(!saved){d.customizationKey=customizationKey;d.presentationLayout='reference';d.manualDescription=true;d.eventRequirements ||= d.events.map(e=>e.type+' · '+(e.date||'Date not fixed')+' · '+e.venue+'\n'+(e.services||'')).join('\n\n');d.description=documentDraft?.description||'';}modal(saved?'Saved invoice '+d.number:'Edit invoice draft',`${saved?'':`<form id="invoice-draft-form">${d.referenceWarning?`<p class="form-error" role="alert">${esc(d.referenceWarning)}</p><label class="check-line"><input type="checkbox" required>I have verified the app’s current payment records</label>`:''}<p class="subtext">Edit the document, preview it, then review before issuing. Financial values come from the booking and recorded receipts.</p><div class="field-grid">${field('billTo','Bill to',d.billTo,'text',null,'required')}${field('date','Invoice date',d.date,'date',null,'required')}${field('termsLabel','Payment terms',d.termsLabel)}<input type="hidden" name="packageName" value="${esc(d.packageName)}">${field('billToAddress','Client billing address',d.billToAddress||'','textarea')}${field('billToPhone','Client phone',d.billToPhone||client(d.client)?.phone||'','tel')}${field('billToEmail','Client email',d.billToEmail||client(d.client)?.email||'','email')}${field('billToTaxId','Client tax / GST number',d.billToTaxId||'')}</div><section class="manual-invoice-description"><h3>Item & Description</h3><p class="subtext">Write paragraphs or lists, just like your original invoice.</p><input type="hidden" name="description" value=""><div id="invoice-description-blocks"></div><button type="button" class="small" data-add-description-block>＋ Add description block</button><p class="subtext">Manual description text stays as entered.</p><input type="hidden" name="eventRequirements" value="${esc(d.eventRequirements||'')}"><input type="hidden" name="deliverablesText" value="${esc(d.deliverables.join('\n'))}"><input type="hidden" name="complimentaryText" value="${esc(d.complimentary.join('\n'))}"></section><details><summary>Invoice appearance</summary><div class="field-grid">${field('invoiceStructure','Invoice structure',d.presentationLayout||'reference','text',[['reference','Original invoice table · Two pages'],['classic','Standard layout']])}${field('invoiceColor','Invoice color',d.theme?.color||'#14655b','color')}${field('invoiceFont','Invoice font',d.theme?.font||'Arial','text',['Arial','Georgia','Verdana'])}</div><label class="check-line"><input type="checkbox" name="invoiceLogoShow" ${d.theme?.showLogo!==false?'checked':''}>Show company logo</label></details><details><summary>Business & signature details</summary>${field('businessName','Business name',d.company.company)}${field('businessAddress','Business address',d.company.address,'textarea')}${field('businessPhone','Business phone',d.company.phone)}${field('businessEmail','Business email',d.company.email)}${field('businessTaxId','Business tax / GST number',d.company.taxId||'')}${field('invoicePaymentInfo','Payment / bank / UPI details',d.company.paymentInfo||'','textarea')}${field('signatory','Authorized signatory',d.company.signatory)}</details><details><summary>Notes & terms</summary>${field('notes','Invoice notes',d.notes,'textarea')}${field('terms','Terms & Conditions',d.terms,'textarea')}</details><details><summary>Pricing & payment records</summary><div class="field-grid">${field('quantity','Quantity',d.quantity||1,'number',null,'min="0.01" step="0.01" required')}${field('unitRate','Rate (₹)',d.unitRate??d.price,'number',null,'min="0" step="0.01" required')}${field('invoiceDiscount','Discount (₹)',d.discount,'number',null,'min="0" step="0.01" required')}</div><button type="button" class="small" data-apply-invoice-pricing>Apply proposed pricing to booking</button><p>Rate ${money(d.price)} · Discount ${money(d.discount)} · Total ${money(d.total)}<br>Received ${money(d.paid)} · Outstanding ${money(d.balance)}</p><p class="subtext">Pricing edits are proposals until you click Apply proposed pricing to booking. Existing receipts and issued invoices are preserved.</p>${btn(d.clientInvoice?'edit:clients:'+d.client:'edit:packages:'+d.package,'Edit booking price','small')}</details><section class="invoice-payment-dates"><h3>Payment received dates</h3><p class="subtext">Change the actual received date here. Save each date to update Payments and this draft.</p>${d.payments.map(p=>`<div class="invoice-payment-date-row">${field('receivedDate-'+p.id,stageName(p.stage)+' · '+money(p.amount),p.date||'','date',null,'data-invoice-payment-date="'+esc(p.id)+'"')}<button type="button" class="small" data-save-invoice-payment-date="${esc(p.id)}">Save payment date</button></div>`).join('')||'<p class="subtext">No payments recorded.</p>'}<p class="form-error" data-payment-date-error role="alert"></p></section><details><summary>Payment row descriptions</summary>${d.payments.map((p,i)=>field('paymentLabel-'+i,'Receipt '+(i+1)+' description',d.paymentLabels?.[p.id]||stageName(p.stage)+' · '+invoicePaymentDate(p.date)+' · '+p.method)).join('')}<p class="subtext">These labels change the document only. Payment amounts, dates and methods are edited through Payments.</p></details>${d.receiptReferenceLayout?'':field('additionalDetails','Additional invoice details',d.additionalDetails||'','textarea')}<button type="submit" class="small">Update preview</button></form>`}<div id="invoice-preview-body">${invoiceMarkup(d)}</div><div class="modal-footer">${btn('close','Close')}${saved?`<button type="button" data-copy-issued-invoice="${esc(saved.id)}">Create editable copy</button><button data-download-invoice class="primary">Download PDF</button>`:'<button type="button" data-download-invoice>Download draft PDF</button><button type="button" data-review-invoice class="primary">Review invoice</button>'}</div>`,'invoice-sheet');if(!saved){renderDescriptionBlocks(d.descriptionBlocks||[d.description||'']);setupInvoiceSections();}}
function invoiceSettings(){const b={...businessDefaults,...store.data.settings.invoiceBusiness};modal('Invoice / Business Settings',`<form id="invoice-settings-form"><p class="form-error" role="alert"></p><div class="field-grid">${field('address','Business address',b.address,'textarea')}${field('phone','Business phone',b.phone,'tel')}${field('email','Business email',b.email,'email')}${field('signatory','Authorized signatory',b.signatory)}${field('terms','Standard Terms & Conditions',b.terms,'textarea')}</div><p class="subtext">Uses the current company name and Wedding Clap logo. Saved invoices keep their original settings.</p><div class="modal-footer">${btn('close','Cancel')}<button type="submit" class="primary">Save settings</button></div></form>`)}
document.addEventListener('submit',e=>{if(e.target.id==='invoice-draft-form'){e.preventDefault();readEditableInvoiceDraft();$('#invoice-preview-body').innerHTML=invoiceMarkup(currentInvoiceDraft);}if(e.target.id==='invoice-settings-form'){e.preventDefault();try{store.setInvoiceSettings(Object.fromEntries(new FormData(e.target)));closeModal();toast('Invoice settings saved')}catch(err){e.target.querySelector('.form-error').textContent=err.message}}});
document.addEventListener('click',async e=>{if(e.target.closest('[data-issue-invoice]')){const issueButton=e.target.closest('[data-issue-invoice]');if(issueButton.disabled)return;issueButton.disabled=true;try{if(currentInvoiceDraft.manualDescription?!currentInvoiceDraft.description?.trim():!currentInvoiceDraft.deliverables.length)throw Error('Enter an item description before issuing');const f=$('#invoice-draft-form');if(f)readEditableInvoiceDraft();const inv=await withInvoiceLock(()=>issueInvoice(store,currentInvoiceDraft));store.storage.removeItem(store.storageKey+'-active-invoice-draft-'+currentInvoiceDraft.client+'-'+(currentInvoiceDraft.package||'client'));render();invoicePreview('',inv.id);toast('Invoice '+inv.number+' saved')}catch(err){toast(err.message)}finally{issueButton.disabled=false}}if(e.target.closest('[data-download-invoice]')){const b=e.target.closest('button');b.disabled=true;b.textContent='Preparing PDF…';try{if($('#invoice-draft-form'))readEditableInvoiceDraft();const blob=await invoicePdf(currentInvoiceDraft),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Wedding-Clap-'+(currentInvoiceDraft.documentKind==='receipt'?'Receipt':currentInvoiceDraft.documentKind==='stage-invoice'?'Stage-Invoice':'Invoice')+'-'+(currentInvoiceDraft.number||'DRAFT')+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Invoice PDF downloaded')}catch(err){toast('PDF could not be generated: '+err.message)}finally{b.disabled=false;b.textContent='Download PDF'}}});

function customizeStages(id){const p=store.data.projects.find(p=>p.id===id);if(!p)return;modal('Customize project stages',`<form id="production-stages-form" data-project="${esc(id)}"><p class="form-error" role="alert"></p><p>Enter one stage per line, in order. Keep Shoot Completed first and Completed last. Keep the current stage to preserve progress.</p>${field('stageNames','Project stages',projectStages(p).join('\n'),'textarea',null,'required')}<button type="button" data-production-defaults>Use new studio stages</button><div class="modal-footer">${btn('close','Cancel')}<button type="submit" class="primary">Save stages</button></div></form>`);}
document.addEventListener('click',e=>{if(e.target.closest('[data-production-defaults]')){const f=$('#production-stages-form'),p=store.data.projects.find(p=>p.id===f.dataset.project),current=projectStages(p)[p.stage],next=[...defaultProductionStages];if(!next.includes(current))next.splice(next.length-1,0,current);f.elements.stageNames.value=next.join('\n');}});
document.addEventListener('submit',e=>{if(e.target.id!=='production-stages-form')return;e.preventDefault();const f=e.target;try{store.update('projects',f.dataset.project,{stageNames:f.elements.stageNames.value.split('\n').map(s=>s.trim()).filter(Boolean)});closeModal();render();toast('Project stages updated');}catch(err){f.querySelector('.form-error').textContent=err.message;}});

document.addEventListener('click',e=>{const button=e.target.closest('[data-production-item]');if(!button)return;const [id,index]=button.dataset.productionItem.split(':'),p=store.data.projects.find(p=>p.id===id);if(!p)return;const label=projectStages(p)[Number(index)],done=completedProjectStages(p),next=done.includes(label)?done.filter(s=>s!==label):[...done,label];try{store.update('projects',id,{completedStages:next});render();toast(label+(next.includes(label)?' marked done':' reopened'));}catch(err){toast(err.message);}});

function syncNewClientPaymentFields(){const f=$('#new-client-form');if(!f)return;const quote=f.elements.status.value==='Quote Sent';for(const key of ['bookingAmount','paymentDate','method'])for(const input of f.querySelectorAll('[data-plan-field="'+key+'"]')){input.closest('.field').hidden=quote;input.disabled=quote;const picker=input.closest('.field').querySelector('[data-date-picker]');if(picker)picker.disabled=quote;} }
document.addEventListener('change',e=>{if(e.target.name==='status'&&e.target.closest('#new-client-form'))syncNewClientPaymentFields();});

function updateNewClientFinalPrice(){const f=$('#new-client-form'),output=$('#new-client-final-price');if(!f||!output)return;try{let total=0;for(const row of f.querySelectorAll('[data-package-plan]')){const amount=finalQuote(row.querySelector('[data-plan-field="price"]').value,row.querySelector('[data-plan-field="discount"]').value);total+=amount;row.querySelector('[data-group-total]').textContent='After discount: '+money(amount);}output.textContent='Total Amount: '+money(total);output.removeAttribute('role');}catch(err){output.textContent=err.message;output.setAttribute('role','alert');}}

document.addEventListener('input',e=>{if(e.target.closest('#new-client-form')&&['price','discount'].includes(e.target.dataset.planField))updateNewClientFinalPrice();});

function syncClientName(){const f=$('#new-client-form');if(!f)return;const automatic=f.elements.useCoupleNames.checked;f.elements.namedItem('name').readOnly=automatic;if(automatic)f.elements.namedItem('name').value=[f.elements.bride.value.trim(),f.elements.groom.value.trim()].filter(Boolean).join(' & ');}
document.addEventListener('change',e=>{if(e.target.name==='useCoupleNames'&&e.target.closest('#new-client-form'))syncClientName();});
document.addEventListener('input',e=>{if(['bride','groom'].includes(e.target.name)&&e.target.closest('#new-client-form'))syncClientName();});

function syncBrideGroomNames(){const f=$('#new-client-form');if(!f)return;const enabled=f.elements.useClientName.checked;f.elements.bride.readOnly=enabled;f.elements.groom.readOnly=enabled;$('#couple-name-hint').hidden=!enabled;if(!enabled)return;const parts=f.elements.namedItem('name').value.trim().split(/\s*(?:&|\+|\band\b)\s*/i);if(parts.length===2&&parts.every(s=>s.trim())){f.elements.bride.value=parts[0].trim();f.elements.groom.value=parts[1].trim();$('#couple-name-hint').textContent='First name is bride; second is groom. Uncheck to edit or swap them.';}else{f.elements.bride.value='';f.elements.groom.value='';$('#couple-name-hint').textContent='Enter two names separated by &, and, or +. First name is bride; second is groom.';}}
document.addEventListener('change',e=>{const f=e.target.closest('#new-client-form');if(!f)return;if(e.target.name==='useClientName'){if(e.target.checked)f.elements.useCoupleNames.checked=false;syncClientName();syncBrideGroomNames();}if(e.target.name==='useCoupleNames'){if(e.target.checked)f.elements.useClientName.checked=false;syncBrideGroomNames();syncClientName();}});
document.addEventListener('input',e=>{if(e.target.name==='name'&&e.target.closest('#new-client-form'))syncBrideGroomNames();});

document.addEventListener('change',e=>{if(e.target.name!=='nameMode'||!e.target.closest('#new-client-form'))return;const f=e.target.closest('form');f.elements.useCoupleNames.checked=e.target.value==='fromCouple';f.elements.useClientName.checked=e.target.value==='fromClient';syncBrideGroomNames();syncClientName();});

function serviceAssignmentRows(e){return `<section class="panel service-crew" aria-label="Services and assigned team"><div class="section-header"><div><h3>Required services & team</h3><p class="service-summary">${serviceList(e.services).length} services · ${serviceList(e.services).filter(service=>store.data.assignments.some(a=>a.event===e.id&&a.service===service)).length} assigned</p></div><button type="button" class="small event-add-service" data-add-event-service="${esc(e.id)}">＋ Add service</button></div><div class="service-card-grid">${serviceList(e.services).map(service=>{const assigned=store.data.assignments.filter(a=>a.event===e.id&&a.service===service);return `<article class="service-crew-row ${assigned.length?'service-assigned':'service-unassigned'}"><div class="service-crew-info"><div class="service-heading"><strong class="required-service-name"><span class="service-dot" aria-hidden="true"></span>${esc(service)}</strong><details class="crew-menu"><summary aria-label="Options for ${esc(service)} service">⋯</summary><div class="crew-menu-actions"><button type="button" class="small danger" data-remove-event-service="${esc(e.id)}" data-remove-service="${esc(service)}" aria-label="Remove ${esc(service)} service">Remove service</button>${assigned.map(a=>`<button type="button" class="small danger" data-action="delete:assignments:${esc(a.id)}" aria-label="Remove ${esc(person(a.member)?.name||'team member')} assignment">Remove ${esc(person(a.member)?.name||'team member')} assignment</button>`).join('')}</div></details></div>${assigned.length?assigned.map(a=>{const due=a.charge-a.paid,status=a.charge===0?'Amount not set':due===0?'Paid':a.paid>0?'Partially paid':'Pending';return `<div class="crew-payment"><small class="assigned-member-label">Assigned member</small><div class="crew-member-line"><span class="crew-avatar" aria-hidden="true">${esc(initials(person(a.member)?.name||'?'))}</span>${btn('edit:assignments:'+a.id,esc(person(a.member)?.name||'Unassigned')+' <span aria-hidden="true">✎</span>','crew-member-edit')}</div><span class="crew-pay-status ${due===0&&a.charge>0?'paid':'pending'}">${status}</span><dl class="crew-amounts"><div><dt>Charge</dt><dd>${money(a.charge)}</dd></div><div><dt>Paid</dt><dd>${money(a.paid)}</dd></div><div><dt>Pending</dt><dd>${money(due)}</dd></div></dl></div>`;}).join(''):'<div class="crew-unassigned"><span>No team assigned</span><button type="button" class="small" data-service-assign="'+esc(e.id)+'" data-assignment-service="'+esc(service)+'">Assign member</button></div>'}</div>${assigned.length>1?'<p class="subtext">Only one member is allowed. Remove the extra assignment.</p>':''}</article>`;}).join('')||'<p class="subtext">No services selected. Add a service to assign your team.</p>'}</div></section>`;}

document.addEventListener('click',e=>{const button=e.target.closest('[data-service-assign]');if(button)assignmentForm('',button.dataset.serviceAssign,button.dataset.assignmentService);});
document.addEventListener('change',e=>{if(e.target.name!=='event'||!e.target.closest('#assignment-form'))return;const f=e.target.closest('form'),required=serviceList(event(e.target.value)?.services).filter(service=>!store.data.assignments.some(a=>a.event===e.target.value&&a.service===service&&a.id!==f.dataset.id));f.elements.service.innerHTML=required.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');refreshAssignmentMembers(f);});

document.addEventListener('change',e=>{if(e.target.closest('#new-client-form')&&(e.target.dataset.dayField==='type'||e.target.dataset.planField==='name')){captureEventDays();capturePackagePlans();renderPackagePlans();}});

document.addEventListener('change',e=>{const el=e.target;if(!el.hasAttribute('data-pricing-event'))return;const f=el.closest('#new-client-form'),day=el.dataset.pricingEvent,group=el.dataset.pricingGroup;if(el.checked){for(const other of f.querySelectorAll('[data-pricing-event="'+day+'"]'))if(other!==el)other.checked=false;f.dataset['dayPackage'+day]=group;f.elements.namedItem('day-package-'+day).value=group;}else{f.dataset['dayPackage'+day]='-1';f.elements.namedItem('day-package-'+day).value='-1';}});

function syncPricingEventAvailability(f){for(const box of f.querySelectorAll('[data-pricing-event]')){const day=box.dataset.pricingEvent,owner=Number(f.elements.namedItem('day-package-'+day).value);box.disabled=owner>=0&&owner!==Number(box.dataset.pricingGroup);box.closest('label').classList.toggle('event-already-priced',box.disabled);box.closest('label').title=box.disabled?'Already selected in another pricing group. Uncheck it there first.':'';}}
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-pricing-event'))syncPricingEventAvailability(e.target.closest('form'));});

document.addEventListener('click',e=>{const button=e.target.closest('[data-date-picker]');if(!button)return;const input=document.getElementById(button.dataset.datePicker);if(!input||input.disabled)return;input.focus();try{if(input.showPicker)input.showPicker();else input.click();}catch{input.focus();}});

document.addEventListener('click',e=>{if(!e.target.closest('[data-create-assignment-member]'))return;const f=e.target.closest('#assignment-form'),error=f.querySelector('[data-new-member-error]');try{const name=f.elements.newMemberName.value.trim();if(!name)throw Error('Enter the team member name');const member=store.add('team',{name,role:f.elements.newMemberRole.value,phone:f.elements.newMemberPhone.value.trim()});refreshAssignmentMembers(f,member.id);f.elements.newMemberName.value='';f.elements.newMemberPhone.value='';f.querySelector('.assignment-new-member').open=false;error.textContent='';assignmentWarning();toast('Team member added and selected');}catch(err){error.textContent=err.message;}});

function assignmentMemberOptions(eventId,assignmentId='',current=''){const identity=t=>t.phone?.replace(/\D/g,'').slice(-10)||t.name.trim().toLowerCase(),used=new Set(store.data.assignments.filter(a=>a.event===eventId&&a.id!==assignmentId).map(a=>person(a.member)).filter(Boolean).map(identity)),seen=new Set(),members=[...store.data.team].sort((a,b)=>Number(b.id===current)-Number(a.id===current));return [['','Select team member'],...members.filter(t=>{const key=identity(t);if(used.has(key)||seen.has(key))return false;seen.add(key);return true;}).map(t=>[t.id,t.name+(t.phone?' · '+t.phone:'')])];}
function refreshAssignmentMembers(f,current=f.elements.member.value){const options=assignmentMemberOptions(f.elements.event.value,f.dataset.id,current);f.elements.member.innerHTML=options.map(([id,name])=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(name)}</option>`).join('');if(!options.some(([id])=>id===current))f.elements.member.value='';}

document.addEventListener('click',e=>{const button=e.target.closest('[data-add-event-service]');if(!button)return;const ev=event(button.dataset.addEventService),available=services.filter(s=>!serviceList(ev.services).includes(s));if(!available.length)return toast('All services have already been added');modal('Add service',`<form id="add-event-service-form" data-service-event="${esc(ev.id)}"><p class="form-error" role="alert"></p>${field('service','Service','', 'text',available,'required')}<div class="modal-footer"><button type="button" data-return-service-event="${esc(ev.id)}">Cancel</button><button type="submit" class="primary">Add service</button></div></form>`);});
document.addEventListener('click',e=>{const button=e.target.closest('[data-return-service-event]');if(button)eventDetail(button.dataset.returnServiceEvent);});
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='add-event-service-form')return;e.preventDefault();try{const ev=event(f.dataset.serviceEvent),service=f.elements.service.value;if(!services.includes(service))throw Error('Select a service');store.update('events',ev.id,{services:[...new Set([...serviceList(ev.services),service])].join(', ')});render();eventDetail(ev.id);toast('Service added. You can now assign a team member.');}catch(err){f.querySelector('.form-error').textContent=err.message;}});

document.addEventListener('click',e=>{const button=e.target.closest('[data-remove-event-service]');if(!button)return;const ev=event(button.dataset.removeEventService),service=button.dataset.removeService;if(store.data.assignments.some(a=>a.event===ev.id&&a.service===service))return toast('Remove this service’s team assignment first.');const remaining=serviceList(ev.services).filter(s=>s!==service);if(!remaining.length)return toast('Keep at least one service for this event.');modal('Remove service?',`<p>Remove ${esc(service)} from ${esc(ev.type)}? You can add it again later.</p><div class="modal-footer"><button type="button" data-return-service-event="${esc(ev.id)}">Cancel</button><button type="button" class="danger" data-confirm-remove-service="${esc(service)}" data-service-event="${esc(ev.id)}">Remove service</button></div>`);});
document.addEventListener('click',e=>{const button=e.target.closest('[data-confirm-remove-service]');if(!button)return;const ev=event(button.dataset.serviceEvent),service=button.dataset.confirmRemoveService;try{if(store.data.assignments.some(a=>a.event===ev.id&&a.service===service))throw Error('Remove this service’s team assignment first.');const remaining=serviceList(ev.services).filter(s=>s!==service);if(!remaining.length)throw Error('Keep at least one service for this event.');store.update('events',ev.id,{services:remaining.join(', ')});render();eventDetail(ev.id);toast('Service removed');}catch(err){toast(err.message);}});

document.addEventListener('toggle',e=>{if(!e.target.matches?.('.crew-menu')||!e.target.open)return;for(const menu of document.querySelectorAll('.crew-menu[open]'))if(menu!==e.target)menu.open=false;},true);

function paymentClientPicker(id=''){const c=client(id);return `<div class="field payment-client-picker"><label for="payment-client-search">Client Name</label><input type="hidden" id="f-client" name="client" value="${esc(c?.id||'')}"><input id="payment-client-search" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="payment-client-results" autocomplete="off" placeholder="Search client name…" value="${esc(c?.name||'')}" required><div id="payment-client-results" role="listbox" aria-label="Matching clients" hidden></div><small id="payment-client-selection" aria-live="polite">${c?esc(c.id):'Select an existing client'}</small></div>`;}
function showPaymentClients(input){const q=input.value.trim().toLocaleLowerCase(),list=$('#payment-client-results'),matches=store.data.clients.filter(c=>!q||c.name.toLocaleLowerCase().includes(q)||c.id.toLocaleLowerCase().includes(q));list.innerHTML=matches.length?matches.map((c,i)=>`<button type="button" role="option" id="payment-client-option-${i}" aria-selected="false" data-payment-client="${esc(c.id)}"><strong>${esc(c.name)}</strong><small>${esc(c.id)}</small></button>`).join(''):'<p class="subtext" role="status">No matching clients</p>';list.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant');input.dataset.activeOption='-1';}
function closePaymentClients(){const input=$('#payment-client-search'),list=$('#payment-client-results');if(!input||!list)return;list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}
function choosePaymentClient(id){const c=client(id),input=$('#payment-client-search');if(!c||!input)return;$('#f-client').value=id;input.value=c.name;input.setCustomValidity('');$('#payment-client-selection').textContent=c.id;closePaymentClients();$('#f-client').dispatchEvent(new Event('change',{bubbles:true}));input.focus();closePaymentClients();}
document.addEventListener('input',e=>{if(e.target.id!=='payment-client-search')return;$('#f-client').value='';e.target.setCustomValidity('Select an existing client from the list');$('#payment-client-selection').textContent='Select an existing client';refreshEventOptions(e.target.closest('form'));showPaymentClients(e.target);});
document.addEventListener('focusin',e=>{if(e.target.id==='payment-client-search')showPaymentClients(e.target);});
document.addEventListener('click',e=>{const option=e.target.closest('[data-payment-client]');if(option)return choosePaymentClient(option.dataset.paymentClient);if(e.target.id==='payment-client-search')showPaymentClients(e.target);else if(!e.target.closest('.payment-client-picker'))closePaymentClients();});
document.addEventListener('focusout',e=>{if(e.target.closest('.payment-client-picker')&&!e.relatedTarget?.closest('.payment-client-picker'))closePaymentClients();});
document.addEventListener('keydown',e=>{if(e.target.id!=='payment-client-search')return;const input=e.target,list=$('#payment-client-results');if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closePaymentClients();return;}if(!['ArrowDown','ArrowUp','Enter'].includes(e.key))return;if(e.key==='Enter'&&list.hidden)return;if(list.hidden)showPaymentClients(input);const options=[...list.querySelectorAll('[data-payment-client]')];let index=Number(input.dataset.activeOption??-1);if(e.key==='Enter'){e.preventDefault();if(options[index])choosePaymentClient(options[index].dataset.paymentClient);return;}e.preventDefault();if(!options.length)return;index=e.key==='ArrowDown'?(index+1)%options.length:(index<=0?options.length-1:index-1);input.dataset.activeOption=String(index);options.forEach((option,i)=>option.setAttribute('aria-selected',String(i===index)));input.setAttribute('aria-activedescendant',options[index].id);options[index].scrollIntoView({block:'nearest'});});

function clientSearchToolbar(){return `<div class="toolbar client-search-toolbar"><div class="client-search-wrap"><input id="search" role="combobox" aria-label="Search clients" aria-autocomplete="list" aria-expanded="false" aria-controls="client-search-results" autocomplete="off" placeholder="Search name, phone or client ID" value="${esc(search)}"><button type="button" data-clear-client-search aria-label="Clear Search" ${search?'':'hidden'}>×</button><div id="client-search-results" role="listbox" aria-label="Matching clients" hidden></div></div>${tabs(['All','Booked','Quote Sent','Negotiation','Tentative','Canceled','Lost','Confirmed','Completed'],filter,'filter')}</div>`;}
function showClientSuggestions(){const input=$('.client-search-wrap #search'),list=$('#client-search-results');if(!input||!list)return;const q=search.trim().toLocaleLowerCase();if(!q){closeClientSuggestions();return;}const rows=store.data.clients.filter(c=>(filter==='All'||c.status===filter)&&clientSearchMatches(c,q));list.innerHTML=rows.length?rows.map((c,i)=>`<button type="button" role="option" id="client-search-option-${i}" aria-selected="false" data-client-search-result="${esc(c.id)}"><span><strong>${esc(c.name)}</strong><small>${esc(c.id)} · ${esc(c.status)}</small></span><span aria-hidden="true">↗</span></button>`).join(''):`<p role="status">No matching clients${filter==='All'?'':' in '+esc(filter)}.</p>`;list.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant');input.dataset.activeOption='-1';}
function closeClientSuggestions(){const input=$('.client-search-wrap #search'),list=$('#client-search-results');if(!input||!list)return;list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}
document.addEventListener('input',e=>{if(e.target.id==='search'&&route==='clients'&&$('#client-search-results'))showClientSuggestions();});
document.addEventListener('focusin',e=>{if(e.target.matches('.client-search-wrap #search'))showClientSuggestions();});
document.addEventListener('click',e=>{const result=e.target.closest('[data-client-search-result]');if(result){closeClientSuggestions();location.hash='#/clients/'+result.dataset.clientSearchResult;return;}if(e.target.closest('[data-clear-client-search]')){search='';render();$('#search').focus();return;}if(e.target.matches('.client-search-wrap #search'))showClientSuggestions();else if(!e.target.closest('.client-search-wrap'))closeClientSuggestions();});
document.addEventListener('focusout',e=>{if(e.target.closest('.client-search-wrap')&&!e.relatedTarget?.closest('.client-search-wrap'))closeClientSuggestions();});
document.addEventListener('keydown',e=>{if(!e.target.matches('.client-search-wrap #search'))return;const input=e.target,list=$('#client-search-results');if(e.key==='Escape'){e.preventDefault();closeClientSuggestions();return;}if(!['ArrowDown','ArrowUp','Enter'].includes(e.key))return;if(e.key==='Enter'&&list.hidden)return;if(list.hidden)showClientSuggestions();const options=[...list.querySelectorAll('[data-client-search-result]')];let index=Number(input.dataset.activeOption??-1);e.preventDefault();if(e.key==='Enter'){if(options[index]){closeClientSuggestions();location.hash='#/clients/'+options[index].dataset.clientSearchResult;}return;}if(!options.length)return;index=e.key==='ArrowDown'?(index+1)%options.length:(index<=0?options.length-1:index-1);input.dataset.activeOption=String(index);options.forEach((option,i)=>option.setAttribute('aria-selected',String(i===index)));input.setAttribute('aria-activedescendant',options[index].id);options[index].scrollIntoView({block:'nearest'});});

function clientSearchMatches(c,query){const q=query.trim().toLocaleLowerCase();return [c.name,c.phone,c.id].some(value=>String(value||'').toLocaleLowerCase().includes(q));}

function syncCustomPaymentStage(){const f=$('#record-form');if(f?.dataset.table!=='payments')return;const input=f.elements.customStage;if(!input)return;const custom=f.elements.stage.value==='Custom';input.closest('.field').hidden=!custom;input.disabled=!custom;input.required=custom;}
document.addEventListener('change',e=>{if(e.target.name==='stage'&&e.target.closest('#record-form'))syncCustomPaymentStage();});
function clientPayments(c){const rows=store.data.payments.filter(p=>p.client===c.id),stages=stageSummary(store.data,c.id);return `<div class="client-payment-dashboard"><section class="payment-overview"><div class="section-header"><div><h2>Payments</h2><p class="subtext">Every receipt, from booking to delivery</p></div><div class="actions">${!store.packages(c.id).length?`<button type="button" class="small" data-client-invoice="${esc(c.id)}">Generate Invoice</button>`:''}${btn('new:payments:'+c.id,'＋ Add payment','primary small')}</div></div><div class="payment-totals"><div><small>Total amount</small><strong>${money(store.quote(c.id))}</strong></div><div><small>Received</small><strong>${money(store.paid(c.id))}</strong></div><div><small>Outstanding</small><strong>${money(store.balance(c.id))}</strong></div></div></section><section class="payment-stages"><div class="section-header"><h3>Payment stages</h3><button type="button" class="small" data-stage-plan-client="${esc(c.id)}">Set stage amounts</button></div><p class="subtext">Stage status uses your expected amount. Setting targets does not change the quotation.</p>${stages.map(stage=>`<details class="payment-stage-card" ${stage.rows.length?'open':''}><summary><span><strong>${esc(stage.name)}</strong><small>${stage.rows.length} ${stage.rows.length===1?'payment':'payments'} · Received ${money(stage.received)}${stage.target===undefined?'':' / '+money(stage.target)}</small></span><span class="tag ${stage.status==='Paid'?'paid':''}">${esc(stage.status)}</span></summary><div class="payment-stage-body">${stage.pending===null?'<p class="subtext">Expected amount not set.</p>':`<p class="subtext">Expected ${money(stage.target)} · Pending ${money(stage.pending)}</p>`}${stage.rows.map(paymentHistoryCard).join('')||'<p class="subtext">No payment recorded for this stage.</p>'}<button type="button" class="small" data-add-stage-payment="${esc(stage.name)}" data-stage-client="${esc(c.id)}">＋ Record payment</button></div></details>`).join('')}</section>${(store.data.invoices||[]).some(i=>i.client===c.id&&i.clientInvoice)?`<section class="panel"><h3>Issued client invoices</h3><div class="actions">${store.data.invoices.filter(i=>i.client===c.id&&i.clientInvoice).map(i=>btn('saved-invoice:'+i.id,'Invoice '+i.number,'small')).join('')}</div></section>`:''}<details class="payment-booking-details"><summary>Pricing groups & historical invoices</summary>${clientFinance(c)}</details></div>`;}
function paymentHistoryCard(p){const docs=(store.data.invoices||[]).filter(i=>i.paymentId===p.id);return `<article class="stage-payment-row"><div class="payment-card-head"><div><strong>${money(p.amount)}</strong><small>${invoicePaymentDate(p.date)} · ${esc(p.method||'Method not recorded')}</small></div><span class="tag">Received</span></div>${p.transactionReference?`<p class="payment-reference">Transaction · ${esc(p.transactionReference)}</p>`:'<p class="payment-reference">Transaction reference not recorded</p>'}${p.reference?`<p class="subtext">Original invoice reference · ${esc(p.reference)}</p>`:''}${p.notes?`<p class="subtext">${esc(p.notes)}</p>`:''}${paymentCorrectionHistory(p.id)}<div class="payment-document-actions"><button type="button" class="small" data-payment-document="${esc(p.id)}" data-document-kind="receipt">${docs.some(d=>d.documentKind==='receipt')?'View receipt':'Create receipt'}</button><button type="button" class="small" data-payment-document="${esc(p.id)}" data-document-kind="stage-invoice">${docs.some(d=>d.documentKind==='stage-invoice')?'View stage invoice':'Create stage invoice'}</button>${btn('edit:payments:'+p.id,'Edit payment','small')}</div>${docs.length?`<p class="subtext">${docs.map(d=>(d.documentKind==='receipt'?'Receipt':'Invoice')+' #'+esc(d.number)).join(' · ')}</p>`:''}</article>`;}
function paymentDocumentMarkup(d){return `<article class="invoice-preview payment-document"><header><div><h2>${esc(d.company.company)}</h2><p>${d.documentKind==='receipt'?'Payment receipt':'Paid stage invoice'} ${d.number?'#'+esc(d.number):'· Draft'}</p></div><img src="logo.png" alt="Wedding Clap logo"></header><div class="invoice-parties"><p><small>Bill to</small><br><strong>${esc(d.billTo)}</strong></p><p>${date(d.date)}<br>${esc(d.stage)}</p></div><div class="receipt-amount"><small>Amount received for this payment</small><strong>${money(d.amount)}</strong></div><dl class="receipt-facts"><div><dt>Payment date</dt><dd>${invoicePaymentDate(d.payment.date)}</dd></div><div><dt>Method</dt><dd>${esc(d.payment.method||'Not recorded')}</dd></div><div><dt>Transaction reference</dt><dd>${esc(d.payment.transactionReference||'Not recorded')}</dd></div>${d.payment.reference?`<div><dt>Original invoice reference</dt><dd>${esc(d.payment.reference)}</dd></div>`:''}</dl><section><h3>Booking summary at issue</h3><p>${esc(bookingName(d.bookingName))}</p><div class="line-items"><span>Total quotation</span><strong>${money(d.quote)}</strong></div><div class="line-items"><span>Received to date</span><strong>${money(d.received)}</strong></div><div class="line-items"><span>Outstanding</span><strong>${money(d.outstanding)}</strong></div></section><p class="subtext">Acknowledges this payment only. Does not create a new charge or alter the booking total.</p>${d.notes?`<p>${esc(d.notes)}</p>`:''}<p class="signature">${esc(d.company.signatory||'Authorized signatory')}<br>Authorized signatory</p></article>`;}
function paymentDocumentPreview(paymentId,kind='receipt',savedId='',editable=false){const saved=(store.data.invoices||[]).find(i=>i.id===savedId)||(store.data.invoices||[]).find(i=>i.paymentId===paymentId&&i.documentKind===kind);
 if(saved&&!editable){currentInvoiceDraft=structuredClone(saved);return modal(`${kind==='receipt'?'Receipt':'Stage invoice'} #${saved.number}`,invoiceMarkup(currentInvoiceDraft)+`<p class="subtext">Issued record preserved. Customize a separate copy to change its presentation.</p><div class="modal-footer">${btn('close','Close')}<button type="button" data-edit-receipt-copy="${esc(saved.id)}">Customize editable copy</button><button data-download-invoice class="primary">Download PDF</button></div>`,'invoice-sheet');}
 const payment=store.data.payments.find(p=>p.id===paymentId);if(!payment)throw Error('Payment not found');let financial;try{financial=invoiceDraft(store,payment.package||'client:'+payment.client);}catch(err){if(!err.message.includes('Allocate all client receipts'))throw err;financial=invoiceDraft(store,'client:'+payment.client);}const receipt=paymentDocumentDraft(store,paymentId,kind);
 const source=saved?.receiptReferenceLayout?saved:financial;const requirements=financial.events.map(e=>e.type+' · '+(e.date||'Date not fixed')+'\n'+(financial.originalReference==='003621'?'1 Cinematographer\n1 Candid Photographer\n1 Traditional Videographer':e.services||'Requirements not recorded')).join('\n\n');
 const draft={...structuredClone(source),...receipt,company:structuredClone(source.company),theme:structuredClone(source.theme),events:structuredClone(financial.events),payments:structuredClone(financial.payments),billTo:source.billTo,notes:source.notes,terms:source.terms,termsLabel:source.termsLabel||'Due on Receipt',receiptReferenceLayout:true,paymentLabels:source.paymentLabels||Object.fromEntries(financial.payments.map(p=>[p.id,(financial.total>0&&p.stage==='Booking Amount'?Math.round(p.amount/financial.total*100)+'% ':'')+stageName(p.stage)+' · '+invoicePaymentDate(p.date)+' · '+p.method])),manualDescription:true,presentationLayout:'reference',customizationKey:(saved?'receipt-copy-':'receipt-')+kind+'-'+paymentId,description:source.description||financial.packageName,eventRequirements:source.eventRequirements||requirements,date:source.receiptReferenceLayout?source.date:payment.date,additionalDetails:source.additionalDetails||'Payment stage: '+receipt.stage+'\nPayment date: '+payment.date+'\nPayment method: '+payment.method+'\nAmount received: '+money(payment.amount)+'\nTransaction reference: '+(payment.transactionReference||'Not recorded')+'\nOriginal invoice reference: '+(payment.reference||financial.originalReference||'Not recorded')};
 if(store.companyId==='default'&&financial.originalReference&&!source.receiptReferenceLayout)draft.theme={...draft.theme,...originalReceiptAssets};delete draft.number;delete draft.id;invoicePreview(financial.clientInvoice?'client:'+financial.client:financial.package,'',draft.customizationKey,draft);
 $('#modal-title').textContent=saved?'Customize receipt copy':'Receipt preview & editor';
 if(saved){$('[data-review-invoice]').remove();const note=document.createElement('p');note.className='subtext';note.textContent='Customized copy only. The issued receipt and its invoice number remain unchanged.';$('#invoice-draft-form').prepend(note);}else $('[data-review-invoice]').textContent='Review receipt';
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-receipt-copy]');if(!b)return;const saved=store.data.invoices.find(i=>i.id===b.dataset.editReceiptCopy);paymentDocumentPreview(saved.paymentId,saved.documentKind,saved.id,true);});

async function withInvoiceLock(action){if(navigator.locks)return navigator.locks.request('wedding-clap-empty-document-number-'+store.companyId,action);return action();}
document.addEventListener('click',async e=>{const doc=e.target.closest('[data-payment-document]');if(doc){try{paymentDocumentPreview(doc.dataset.paymentDocument,doc.dataset.documentKind)}catch(err){toast(err.message);}return;}const issue=e.target.closest('[data-issue-payment-document]');if(issue){if(issue.disabled)return;issue.disabled=true;try{const draft=structuredClone(currentInvoiceDraft),saved=await withInvoiceLock(()=>issuePaymentDocument(store,draft,saveIssuedDocument));render();paymentDocumentPreview(saved.paymentId,saved.documentKind,saved.id);toast('Document #'+saved.number+' issued');}catch(err){toast(err.message);}finally{issue.disabled=false}return;}const stage=e.target.closest('[data-add-stage-payment]');if(stage){form('payments','',stage.dataset.stageClient);const f=$('#record-form');f.elements.stage.innerHTML+=`<option value="${esc(stage.dataset.addStagePayment)}">${esc(stage.dataset.addStagePayment)}</option>`;f.elements.stage.value=stage.dataset.addStagePayment;syncCustomPaymentStage();return;}const plan=e.target.closest('[data-stage-plan-client]');if(plan){const id=plan.dataset.stagePlanClient,stages=stageSummary(store.data,id);modal('Set stage amounts',`<form id="payment-stage-plan-form" data-stage-client="${esc(id)}"><p class="form-error" role="alert"></p><p class="subtext">Optional targets within the quotation. Leave blank for Not set; use zero for Not required.</p><div class="field-grid">${stages.map((stage,i)=>field('target-'+i,stage.name,stage.target??'','number',null,'min="0" step="1" data-stage-name="'+esc(stage.name)+'"')).join('')}${field('newStage','Optional custom stage name')}${field('newTarget','Custom stage expected amount (₹)','','number',null,'min="0" step="1"')}</div><div class="modal-footer">${btn('close','Cancel')}<button class="primary">Save targets</button></div></form>`);}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='payment-stage-plan-form')return;e.preventDefault();try{const inputs=[...f.querySelectorAll('[data-stage-name]')],plan={};for(const input of inputs)if(input.value!==''){const amount=Number(input.value);if(!Number.isFinite(amount)||amount<0)throw Error('Enter valid stage amounts');plan[input.dataset.stageName]=amount;}const custom=String(f.elements.newStage.value||'').trim();if(custom){const name=stageName(custom);if(inputs.some(input=>input.dataset.stageName===name))throw Error('Use the existing stage field for '+name);if(f.elements.newTarget.value==='')throw Error('Enter the custom stage expected amount');plan[name]=Number(f.elements.newTarget.value);if(!Number.isFinite(plan[name])||plan[name]<0)throw Error('Enter a valid custom stage amount');}if(Object.values(plan).reduce((n,v)=>n+v,0)>store.quote(f.dataset.stageClient))throw Error('Stage targets cannot exceed the quotation');const before=structuredClone(store.data);try{store.data.settings.paymentStagePlans={...store.data.settings.paymentStagePlans,[f.dataset.stageClient]:plan};store.save();}catch(err){store.data=before;throw err;}closeModal();render();toast('Stage amounts saved');}catch(err){f.querySelector('.form-error').textContent=err.message;}});

function paymentCorrectionHistory(id){const audits=(store.data.paymentAudit||[]).filter(a=>a.payment===id);return audits.length?`<details class="payment-corrections"><summary>${audits.length} ${audits.length===1?'correction':'corrections'} · View history</summary>${audits.map(a=>`<p class="subtext">${esc(a.at)}<br>Previous: ${money(a.before.amount)} · ${date(a.before.date)} · ${esc(a.before.method||'Not set')} · ${esc(stageName(a.before.stage))}<br>Updated: ${money(a.after.amount)} · ${date(a.after.date)} · ${esc(a.after.method||'Not set')} · ${esc(stageName(a.after.stage))}</p>`).join('')}</details>`:'';}

function invoiceMarkup(d){let html=(d.manualDescription||d.presentationLayout==='reference')?referenceInvoiceMarkup(d):originalInvoiceMarkup(d);if(!d.theme&&!receiptTheme(d).signatureImage)return html;const theme=receiptTheme(d),fonts=['Arial','Georgia','Verdana'],font=fonts.includes(theme.font)?theme.font:'Arial',color=/^#[0-9a-f]{6}$/i.test(theme.color)?theme.color:'#14655b',textColor=/^#[0-9a-f]{6}$/i.test(theme.textColor)?theme.textColor:'#283b32';html=html.replace('<article class="invoice-preview','<article style="--invoice-accent:'+color+';color:'+textColor+';font-family:'+font+'" class="themed-invoice theme-'+esc(theme.layout||'classic')+' invoice-preview');html=html.replace('<img src="logo.png" alt="Wedding Clap logo">',theme.showLogo!==false&&theme.logo?'<img src="'+esc(theme.logo)+'" alt="Company logo">':'');if(d.documentKind&&!d.receiptReferenceLayout){const contact=[d.company.address,d.company.phone,d.company.email].filter(Boolean).map(value=>esc(value).replaceAll('\n','<br>')).join('<br>');if(contact)html=html.replace('</header>','</header><p class="invoice-company-contact">'+contact+'</p>');}const extra=(d.company.paymentInfo?'<section><h3>Payment information</h3><p>'+esc(d.company.paymentInfo).replaceAll('\n','<br>')+'</p></section>':'')+(d.documentKind&&!d.receiptReferenceLayout&&d.company.terms?'<details><summary>Terms & conditions</summary><p>'+esc(d.company.terms).replaceAll('\n','<br>')+'</p></details>':'')+(theme.signatureImage?'<img class="invoice-signature-image" src="'+esc(theme.signatureImage)+'" alt="Authorized signature">':'');if(theme.signatureImage){html=html.replace('<p class="signature">','<img class="invoice-signature-image" src="'+esc(theme.signatureImage)+'" alt="Authorized signature"><p class="signature">');return html.replace('</article>',extra.replace('<img class="invoice-signature-image" src="'+esc(theme.signatureImage)+'" alt="Authorized signature">','')+'</article>');}return html.replace('</article>',extra+'</article>');}
function companyList(){let companies;try{companies=JSON.parse(localStorage.getItem('wedding-clap-empty-company-registry')||'[]')}catch{companies=[]}return [{id:'default',name:store.companyId==='default'?store.data.settings.company:'Wedding Clap'},...companies.filter(c=>c.id!=='default').map(c=>c.id===store.companyId?{...c,name:store.data.settings.company}:c)];}
function companyWorkspacePanel(){return `<section class="panel company-workspace"><div class="section-header"><div><h2>Company workspace</h2><p class="subtext">Separate clients, payments, templates and document numbering</p></div><button type="button" class="small" data-new-company>＋ Company</button></div><label for="company-workspace-select">Active company</label><select id="company-workspace-select">${companyList().map(c=>`<option value="${esc(c.id)}" ${c.id===store.companyId?'selected':''}>${esc(c.name)}</option>`).join('')}</select><p class="subtext">Local workspaces on this browser. Accounts and server access controls are required for hosted company isolation.</p></section>`;}
function brandingSettingsPanel(){const templates=(store.data.settings.invoiceTemplates||[]).filter(t=>!t.archived),numbering=store.data.settings.invoiceNumbering||{prefix:'',padding:6};return `<section class="panel branding-settings"><div class="section-header"><div><h2>Invoice Theme & Branding</h2><p class="subtext">Customize future invoices and receipts</p></div><div class="actions"><button type="button" class="small" data-branding-new>New template</button><button type="button" class="primary small" data-branding-edit>Customize</button></div></div>${templates.length?`<div class="branding-template-list">${templates.map(t=>`<div class="branding-template-row"><span><strong>${esc(t.name)}</strong><small>${esc(t.theme.font)} · ${esc(t.theme.layout)}${t.id===store.data.settings.activeInvoiceTemplate?' · Default':''}</small></span><div class="actions"><button type="button" class="small" data-branding-edit="${esc(t.id)}">Edit</button><button type="button" class="small" data-branding-duplicate="${esc(t.id)}">Duplicate</button>${t.id===store.data.settings.activeInvoiceTemplate?'':`<button type="button" class="small" data-branding-default="${esc(t.id)}">Set default</button>`}<button type="button" class="small" data-branding-archive="${esc(t.id)}">Archive</button></div></div>`).join('')}</div>`:'<p class="subtext">No saved templates. Start with the studio default.</p>'}${(store.data.settings.invoiceTemplates||[]).some(t=>t.archived)?`<details><summary>Archived templates</summary>${store.data.settings.invoiceTemplates.filter(t=>t.archived).map(t=>`<div class="branding-template-row"><span>${esc(t.name)}</span><button type="button" class="small" data-branding-restore="${esc(t.id)}">Restore</button></div>`).join('')}</details>`:''}<details class="branding-numbering"><summary>Invoice numbering · Next ${esc(numbering.prefix+String(Math.max(store.companyId==='default'?3622:1,store.data.nextInvoice||0)).padStart(numbering.padding,'0'))}</summary><form id="branding-numbering-form"><p class="form-error" role="alert"></p><div class="field-grid">${field('prefix','Invoice prefix',numbering.prefix)}${field('padding','Number digits',numbering.padding,'number',null,'min="3" max="10" required')}${field('next','Next sequence number',Math.max(store.companyId==='default'?3622:1,store.data.nextInvoice||0),'number',null,'min="1" required')}</div><button class="small primary">Save numbering</button><p class="subtext">A shared sequence for invoices and receipts in this company. Issued numbers are never reused.</p></form></details></section>`;}
let brandingDraft=null;
function brandingEditor(id='',duplicate=false){const saved=(store.data.settings.invoiceTemplates||[]).find(t=>t.id===id),brand=selectedBranding(store);brandingDraft=structuredClone(saved||{name:'Studio template',theme:brand.theme,business:{...(store.companyId==='default'?businessDefaults:neutralBusiness),...brand.business,company:store.data.settings.company}});if(duplicate){delete brandingDraft.id;brandingDraft.name+=' copy';}const b=brandingDraft.business,t=brandingDraft.theme;modal('Invoice Theme & Branding',`<form id="branding-editor-form"><p class="form-error" role="alert"></p><div class="branding-editor-grid"><div class="branding-controls">${field('templateName','Template name',brandingDraft.name,'text',null,'required maxlength="80"')}<details open><summary>Appearance</summary><div class="field-grid">${field('color','Brand color',t.color,'color')}${field('textColor','Text color',t.textColor,'color')}${field('font','Font',t.font,'text',['Arial','Georgia','Verdana'])}${field('layout','Layout',t.layout,'text',[['classic','Classic'],['minimal','Minimal'],['compact','Compact']])}</div><label class="check-line"><input type="checkbox" name="showLogo" ${t.showLogo!==false?'checked':''}>Show logo</label><label class="branding-upload">Upload logo<input type="file" data-branding-image="logo" accept="image/png,image/jpeg,image/webp"></label><button type="button" class="small" data-branding-remove-image="logo">Remove logo</button></details><details><summary>Business details</summary>${field('businessName','Business name',b.company||store.data.settings.company)}${field('address','Business address',b.address,'textarea')}${field('phone','Business phone',b.phone,'tel')}${field('email','Business email',b.email,'email')}</details><details><summary>Payment information</summary>${field('paymentInfo','UPI / bank details / payment instructions',b.paymentInfo||'','textarea')}</details><details><summary>Signature</summary>${field('signatory','Authorized signatory',b.signatory)}<label class="branding-upload">Upload signature<input type="file" data-branding-image="signatureImage" accept="image/png,image/jpeg,image/webp"></label><button type="button" class="small" data-branding-remove-image="signatureImage">Remove signature image</button></details><details><summary>Terms & conditions</summary>${field('terms','Standard terms & conditions',b.terms,'textarea')}</details><p class="subtext">Changes apply to future documents. Issued invoices retain their saved design and details.</p></div><div class="branding-live-preview"><div class="section-header"><h3>Live preview</h3><button type="button" class="small" data-branding-sample-pdf>Sample PDF</button></div><p class="subtext">Sample data · No invoice number is issued</p><div id="branding-live-preview-body" aria-label="Invoice preview"></div></div></div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">Save template</button></div></form>`,'branding-sheet');refreshBrandingPreview();}
function readBrandingEditor(){const f=$('#branding-editor-form');if(!f)return brandingDraft;return {...brandingDraft,name:f.elements.templateName.value,theme:{...brandingDraft.theme,color:f.elements.color.value,textColor:f.elements.textColor.value,font:f.elements.font.value,layout:f.elements.layout.value,showLogo:f.elements.showLogo.checked},business:{company:f.elements.businessName.value,address:f.elements.address.value,phone:f.elements.phone.value,email:f.elements.email.value,paymentInfo:f.elements.paymentInfo.value,signatory:f.elements.signatory.value,terms:f.elements.terms.value}};}
function brandingSampleDraft(){const d=readBrandingEditor(),numbering=store.data.settings.invoiceNumbering||{prefix:'',padding:6};return {theme:d.theme,company:d.business,number:numbering.prefix+String(Math.max(store.companyId==='default'?3622:1,store.data.nextInvoice||0)).padStart(numbering.padding,'0'),billTo:'Sample Client',date:today(),termsLabel:'Due on Receipt',packageName:'Photography booking',price:50000,discount:5000,total:45000,paid:10000,balance:35000,events:[{type:'Wedding',date:today(),venue:'Sample venue',city:'',start:'',end:'',timeNotRecorded:true,services:'Cinematic, Candid'}],payments:[{stage:'Booking Amount',date:today(),method:'UPI',amount:10000}],deliverables:['Edited photographs','Cinematic film'],complimentary:[],notes:'Thank you for choosing '+d.business.company,terms:d.business.terms};}
function refreshBrandingPreview(){$('#branding-live-preview-body').innerHTML=invoiceMarkup(brandingSampleDraft());}
document.addEventListener('input',e=>{if(e.target.closest('#branding-editor-form')&&!e.target.matches('[type=file]'))refreshBrandingPreview();});
document.addEventListener('change',async e=>{if(e.target.id==='company-workspace-select'){const id=e.target.value;if(!companyList().some(c=>c.id===id))return;store=new Store(localStorage,id);localStorage.setItem('wedding-clap-empty-active-company',id);closeModal();search='';filter='All';location.hash='#/settings';render();return;}if(e.target.closest('#branding-editor-form')&&!e.target.matches('[type=file]'))refreshBrandingPreview();const key=e.target.dataset.brandingImage;if(!key)return;const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500000)throw Error('Choose a PNG, JPG or WebP image below 500 KB');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});brandingDraft=readBrandingEditor();brandingDraft.theme[key]=data;refreshBrandingPreview();}catch(err){$('#branding-editor-form .form-error').textContent=err.message;}});
document.addEventListener('click',e=>{const edit=e.target.closest('[data-branding-edit]'),copy=e.target.closest('[data-branding-duplicate]'),active=e.target.closest('[data-branding-default]'),archive=e.target.closest('[data-branding-archive]'),remove=e.target.closest('[data-branding-remove-image]');if(e.target.closest('[data-branding-new]'))return brandingEditor();if(edit)return brandingEditor(edit.dataset.brandingEdit||store.data.settings.activeInvoiceTemplate||'');if(copy)return brandingEditor(copy.dataset.brandingDuplicate,true);if(remove){brandingDraft=readBrandingEditor();brandingDraft.theme[remove.dataset.brandingRemoveImage]='';refreshBrandingPreview();return;}if(active||archive){const before=structuredClone(store.data);try{const id=active?.dataset.brandingDefault||archive.dataset.brandingArchive;if(active)store.data.settings.activeInvoiceTemplate=id;else{store.data.settings.invoiceTemplates.find(t=>t.id===id).archived=true;if(store.data.settings.activeInvoiceTemplate===id)store.data.settings.activeInvoiceTemplate=store.data.settings.invoiceTemplates.find(t=>!t.archived)?.id||'';}store.save();render();toast(active?'Default template updated':'Template archived. Issued invoices preserved');}catch(err){store.data=before;toast(err.message)}return;}if(e.target.closest('[data-new-company]'))modal('Create company workspace',`<form id="new-company-form"><p class="form-error" role="alert"></p>${field('name','Company name','','text',null,'required')}<p class="subtext">Creates an empty, separate workspace. The current company remains intact.</p><div class="modal-footer">${btn('close','Cancel')}<button class="primary">Create company</button></div></form>`);});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='branding-editor-form'){e.preventDefault();try{saveTemplate(store,readBrandingEditor());closeModal();render();toast('Invoice template saved');}catch(err){f.querySelector('.form-error').textContent=err.message}}if(f.id==='branding-numbering-form'){e.preventDefault();try{saveNumbering(store,Object.fromEntries(new FormData(f)));render();toast('Invoice numbering saved');}catch(err){f.querySelector('.form-error').textContent=err.message}}if(f.id==='new-company-form'){e.preventDefault();try{const name=f.elements.name.value.trim();if(!name)throw Error('Enter a company name');const id=crypto.randomUUID(),company=new Store(localStorage,id);company.data.settings.company=name;company.save();const registry=companyList();localStorage.setItem('wedding-clap-empty-company-registry',JSON.stringify([...registry,{id,name}]));closeModal();render();toast('Company created. Select it to open its workspace.');}catch(err){f.querySelector('.form-error').textContent=err.message}}});

document.addEventListener('click',e=>{const restore=e.target.closest('[data-branding-restore]');if(!restore)return;const before=structuredClone(store.data);try{const t=store.data.settings.invoiceTemplates.find(t=>t.id===restore.dataset.brandingRestore);t.archived=false;store.save();render();toast('Template restored');}catch(err){store.data=before;toast(err.message);}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-branding-sample-pdf]');if(!b)return;b.disabled=true;try{const draft=brandingSampleDraft();draft.number='SAMPLE';const blob=await invoicePdf(draft),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Invoice-Branding-Sample.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Sample PDF downloaded');}catch(err){toast(err.message)}finally{b.disabled=false}});

function readEditableInvoiceDraft(){const f=$('#invoice-draft-form');if(!f)return;const values=Object.fromEntries(invoiceSectionFormData(f));currentInvoiceDraft.descriptionBlocks=[...f.querySelectorAll('[data-description-block]')].map(input=>input.value);values.description=currentInvoiceDraft.descriptionBlocks.join('\n\n');f.elements.description.value=values.description;for(const k of ['billTo','billToAddress','billToPhone','billToEmail','billToTaxId','date','termsLabel','packageName','description','eventRequirements','notes','terms'])currentInvoiceDraft[k]=values[k];if(f.elements.additionalDetails)currentInvoiceDraft.additionalDetails=values.additionalDetails;currentInvoiceDraft.quantity=Number(values.quantity);currentInvoiceDraft.unitRate=Number(values.unitRate);currentInvoiceDraft.price=Math.round(currentInvoiceDraft.quantity*currentInvoiceDraft.unitRate*100)/100;currentInvoiceDraft.discount=Number(values.invoiceDiscount);currentInvoiceDraft.total=currentInvoiceDraft.price-currentInvoiceDraft.discount;currentInvoiceDraft.balance=currentInvoiceDraft.total-currentInvoiceDraft.paid;currentInvoiceDraft.paymentLabels=Object.fromEntries(currentInvoiceDraft.payments.map((p,i)=>[p.id,values['paymentLabel-'+i]]));currentInvoiceDraft.deliverables=values.deliverablesText.split('\n').map(s=>s.trim()).filter(Boolean);currentInvoiceDraft.complimentary=values.complimentaryText.split('\n').map(s=>s.trim()).filter(Boolean);currentInvoiceDraft.presentationLayout=values.invoiceStructure;currentInvoiceDraft.theme={...currentInvoiceDraft.theme,color:values.invoiceColor,font:values.invoiceFont,showLogo:values.invoiceLogoShow==='on'};currentInvoiceDraft.company={...currentInvoiceDraft.company,company:values.businessName,address:values.businessAddress,phone:values.businessPhone,email:values.businessEmail,signatory:values.signatory,taxId:values.businessTaxId,paymentInfo:values.invoicePaymentInfo};}
function referenceInvoiceMarkup(d){return `<article class="invoice-preview reference-invoice"><header><div><h2>${esc(d.company.company)}</h2><p>${d.documentKind==='receipt'?'Receipt':d.documentKind==='stage-invoice'?'Stage Invoice':'Invoice'} #${d.number?esc(d.number):'DRAFT'}</p><small>Balance Due</small><strong>${money(d.balance)}</strong></div><img src="logo.png" alt="Wedding Clap logo"></header><p class="reference-company">${esc(d.company.company)}<br>${esc(d.company.address).replaceAll('\n','<br>')}<br>${esc(d.company.phone)}<br>${esc(d.company.email)}</p><div class="invoice-parties"><p>${d.documentKind==='receipt'?'Receipt Date':'Invoice Date'}: ${date(d.date)}<br>Terms: ${esc(d.termsLabel)}</p><p><small>Bill To</small><br><strong>${esc(d.billTo)}</strong><br>${esc(d.billToAddress||'').replaceAll('\n','<br>')}<br>${esc([d.billToPhone,d.billToEmail,d.billToTaxId].filter(Boolean).join(' · '))}</p></div>${d.company.taxId?'<p>Tax / GST ID: '+esc(d.company.taxId)+'</p>':''}<div class="reference-table-scroll"><table class="reference-table"><thead><tr><th>#</th><th>Item & Description</th><th>Qty</th><th>Rate</th><th>Discount</th><th>Amount</th></tr></thead><tbody><tr><td>1</td><td>${d.manualDescription?descriptionHtml(d.description||'',esc):`<strong>${esc(d.packageName)}</strong><p>${esc(d.description||'').replaceAll('\n','<br>')}</p>${d.eventRequirements?'<p>'+esc(d.eventRequirements).replaceAll('\n','<br>')+'</p>':''}<p>Deliverables<br>${d.deliverables.map(x=>'– '+esc(x)).join('<br>')}</p>${d.complimentary.length?'<p>Complimentary<br>'+d.complimentary.map(esc).join('<br>')+'</p>':''}`}</td><td>${esc(d.quantity||1)}</td><td>${money(d.unitRate??d.price)}</td><td>${money(d.discount)}</td><td>${money(d.total)}</td></tr>${d.payments.map((p,i)=>`<tr><td>${i+2}</td><td>${esc(invoicePaymentLabel(p,d.paymentLabels?.[p.id]))}${p.transactionReference?'<br>'+esc(p.transactionReference):''}</td><td>1.00</td><td>−${money(p.amount)}</td><td>0.00</td><td>−${money(p.amount)}</td></tr>`).join('')}</tbody></table></div><div class="reference-totals"><p>Sub Total <strong>${money(d.balance)}</strong></p><p>Total <strong>${money(d.balance)}</strong></p><p class="reference-balance">Balance Due <strong>${money(d.balance)}</strong></p><p class="reference-total-words"><span>Total in Words</span><strong>${esc(amountWords(d.balance))}</strong></p></div>${!d.receiptReferenceLayout&&d.additionalDetails?'<section><h3>Additional details</h3><p>'+esc(d.additionalDetails).replaceAll('\n','<br>')+'</p></section>':''}<section><h3>Notes</h3><p>${esc(d.notes).replaceAll('\n','<br>')}</p></section><section class="reference-terms"><h3>Terms & Conditions</h3><p>${esc(d.terms).replaceAll('\n','<br>')}</p><p class="signature">${esc(d.company.signatory)}<br>${esc(d.company.company)}</p></section></article>`;}
document.addEventListener('change',e=>{if(!e.target.closest('#invoice-draft-form'))return;readEditableInvoiceDraft();$('#invoice-preview-body').innerHTML=invoiceMarkup(currentInvoiceDraft);});
document.addEventListener('input',e=>{if(!e.target.closest('#invoice-draft-form'))return;readEditableInvoiceDraft();$('#invoice-preview-body').innerHTML=invoiceMarkup(currentInvoiceDraft);});
document.addEventListener('click',e=>{if(!e.target.closest('[data-review-invoice]'))return;const f=$('#invoice-draft-form');if(!f.reportValidity())return;readEditableInvoiceDraft();const d=currentInvoiceDraft;if(!Number.isFinite(d.total)||d.quantity<=0||d.discount<0||d.total<d.paid)return toast('Enter valid pricing that covers recorded payments');if(d.documentKind){readEditableInvoiceDraft();return modal('Review receipt',invoiceMarkup(d)+'<div class="modal-footer"><button type="button" data-invoice-back-edit>Back to edit</button><button type="button" class="primary" data-issue-payment-document>Issue receipt</button></div>','invoice-sheet');}const live=invoiceDraft(store,d.clientInvoice?'client:'+d.client:d.package);if(d.total!==live.total||d.price!==live.price||d.discount!==live.discount)return toast('Apply proposed pricing to the booking before reviewing');if(d.manualDescription?!d.description?.trim():!d.deliverables.length)return toast('Enter an item description');modal('Review invoice',`${invoiceMarkup(d)}<p class="subtext">Issue assigns the next unique number and saves an immutable snapshot. It does not change the booking or payments.</p><div class="modal-footer"><button type="button" data-invoice-back-edit>Back to edit</button><button type="button" class="primary" data-issue-invoice>Issue invoice</button></div>`,'invoice-sheet');});
document.addEventListener('click',e=>{if(!e.target.closest('[data-invoice-back-edit]'))return;const draft=structuredClone(currentInvoiceDraft);invoicePreview(draft.clientInvoice?'client:'+draft.client:draft.package,'',draft.customizationKey||'',draft.documentKind?draft:null);currentInvoiceDraft=draft;const f=$('#invoice-draft-form');f.elements.invoiceStructure.value=draft.presentationLayout||'reference';f.elements.invoiceColor.value=draft.theme.color;f.elements.invoiceFont.value=draft.theme.font;f.elements.invoiceLogoShow.checked=draft.theme.showLogo!==false;const values={...draft,unitRate:draft.unitRate??draft.price,quantity:draft.quantity||1,invoiceDiscount:draft.discount,businessTaxId:draft.company.taxId||'',invoicePaymentInfo:draft.company.paymentInfo||'',...Object.fromEntries(draft.payments.map((p,i)=>['paymentLabel-'+i,draft.paymentLabels?.[p.id]||stageName(p.stage)+' · '+invoicePaymentDate(p.date)+' · '+p.method])),deliverablesText:draft.deliverables.join('\n'),complimentaryText:draft.complimentary.join('\n'),businessName:draft.company.company,businessAddress:draft.company.address,businessPhone:draft.company.phone,businessEmail:draft.company.email,signatory:draft.company.signatory};for(const [k,v]of Object.entries(values))if(f.elements[k])f.elements[k].value=v;renderDescriptionBlocks(draft.descriptionBlocks||[draft.description||'']);$('#invoice-preview-body').innerHTML=invoiceMarkup(draft);});

document.addEventListener('click',e=>{const b=e.target.closest('[data-client-invoice]');if(b)invoicePreview('client:'+b.dataset.clientInvoice);});

document.addEventListener('click',e=>{if(!e.target.closest('[data-import-original-invoices]'))return;try{const result=importOriginalInvoices(store);render();modal('Original invoices reconciled',`<p>${result.changes.length?result.changes.map(esc).join('<br>'):'All four invoices are already reconciled.'}</p>${result.clients.map(c=>`<section class="panel"><h3>${esc(c.name)}</h3><p>Total ${money(c.total)} · Received ${money(c.received)} · Outstanding ${money(c.outstanding)}</p><a href="#/clients/${esc(c.id)}" data-close-link>Open client</a></section>`).join('')}<p class="subtext">Prior data backed up in this company’s browser storage. Existing issued invoices remain unchanged.</p>`);}catch(err){toast('Invoice import stopped: '+err.message)}});

document.addEventListener('click',e=>{if(!e.target.closest('[data-apply-invoice-pricing]'))return;try{readEditableInvoiceDraft();const d=currentInvoiceDraft;if(!Number.isFinite(d.price)||!Number.isFinite(d.discount)||d.quantity<=0||d.price<0||d.discount<0||d.discount>d.price||d.total<d.paid)throw Error('Enter valid pricing that covers recorded payments');if(d.clientInvoice)store.reviseQuote('clients',d.client,{price:d.price,discount:d.discount});else{const p=store.data.packages.find(p=>p.id===d.package);store.savePackage({...p,price:d.price,discount:d.discount},p.id);}$('#invoice-preview-body').innerHTML=invoiceMarkup(d);toast('Booking pricing updated. Existing receipts and invoices preserved.');}catch(err){toast(err.message);}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-copy-issued-invoice]');if(!b)return;const saved=store.data.invoices.find(i=>i.id===b.dataset.copyIssuedInvoice);if(!saved)return;invoicePreview(saved.clientInvoice?'client:'+saved.client:saved.package,'','copy-'+saved.id);const live=currentInvoiceDraft;if(store.storage.getItem(store.storageKey+'-invoice-sections-'+live.client+'-'+live.customizationKey)){toast('Saved editable copy loaded. Historical invoice preserved.');return;}for(const k of ['billTo','billToAddress','billToPhone','billToEmail','billToTaxId','termsLabel','packageName','description','descriptionBlocks','eventRequirements','additionalDetails','notes','terms','deliverables','complimentary','theme','company','paymentLabels'])if(saved[k]!==undefined&&(k!=='description'||saved.manualDescription))live[k]=structuredClone(saved[k]);const f=$('#invoice-draft-form'),values={...live,deliverablesText:live.deliverables.join('\n'),complimentaryText:live.complimentary.join('\n'),businessName:live.company.company,businessAddress:live.company.address,businessPhone:live.company.phone,businessEmail:live.company.email,businessTaxId:live.company.taxId||'',invoicePaymentInfo:live.company.paymentInfo||'',signatory:live.company.signatory,invoiceColor:live.theme?.color||'#14655b',invoiceFont:live.theme?.font||'Arial',...Object.fromEntries(live.payments.map((p,i)=>['paymentLabel-'+i,live.paymentLabels?.[p.id]||stageName(p.stage)+' · '+invoicePaymentDate(p.date)+' · '+p.method]))};for(const [k,v]of Object.entries(values))if(f.elements[k])f.elements[k].value=v;f.elements.invoiceLogoShow.checked=live.theme?.showLogo!==false;renderDescriptionBlocks(live.descriptionBlocks||[live.description||'']);$('#invoice-preview-body').innerHTML=invoiceMarkup(live);toast('Editable copy created. Financial values use current records.');});

function renderDescriptionBlocks(blocks=['']){const host=$('#invoice-description-blocks');if(!host)return;host.innerHTML=blocks.map((text,i)=>`<section class="description-edit-block"><div class="description-block-head"><label for="description-block-${i}">Description ${i+1}</label><button type="button" class="small danger" data-remove-description-block="${i}" aria-label="Remove description ${i+1}">Remove</button></div><div class="description-format-tools" aria-label="Format description ${i+1}"><button type="button" class="small" data-description-format="bold" data-description-index="${i}"><strong>Bold</strong></button><button type="button" class="small" data-description-format="italic" data-description-index="${i}"><em>Italic</em></button><button type="button" class="small" data-description-format="bullet" data-description-index="${i}">Bullet list</button></div><textarea id="description-block-${i}" data-description-block="${i}" aria-label="Item description ${i+1}" placeholder="Write your item description…">${esc(text)}</textarea></section>`).join('');}
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-description-format]'))e.preventDefault();});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-description-block]'),remove=e.target.closest('[data-remove-description-block]'),format=e.target.closest('[data-description-format]');if(!add&&!remove&&!format)return;readEditableInvoiceDraft();let blocks=[...currentInvoiceDraft.descriptionBlocks];if(add){blocks.push('');renderDescriptionBlocks(blocks);[...document.querySelectorAll('#invoice-description-blocks textarea')].at(-1)?.focus();}if(remove){blocks.splice(Number(remove.dataset.removeDescriptionBlock),1);renderDescriptionBlocks(blocks);}if(format){const input=$('[data-description-block="'+format.dataset.descriptionIndex+'"]'),start=input.selectionStart,end=input.selectionEnd,selection=input.value.slice(start,end);if(!selection&&format.dataset.descriptionFormat!=='bullet'){toast('Select the text you want to format');input.focus();return;}const marker=format.dataset.descriptionFormat==='bold'?'**':'*';const replacement=format.dataset.descriptionFormat==='bullet'?(selection||'').split('\n').map(line=>'- '+line).join('\n'):marker+selection+marker;input.setRangeText(replacement,start,end,'select');input.focus();}readEditableInvoiceDraft();$('#invoice-preview-body').innerHTML=invoiceMarkup(currentInvoiceDraft);});

// Document-only section overrides are kept outside the booking ledger.
function setupInvoiceSections(){
 const f=$('#invoice-draft-form');if(!f)return;
 const d=currentInvoiceDraft;const slot=store.storageKey+'-active-invoice-draft-'+d.client+'-'+(d.package||'client');if(!d.customizationKey){d.customizationKey=store.storage.getItem(slot)||crypto.randomUUID();store.storage.setItem(slot,d.customizationKey);}const key=store.storageKey+'-invoice-sections-'+d.client+'-'+d.customizationKey;
 const fields=el=>[...el.querySelectorAll('[name]')].filter(x=>x.type!=='hidden');
 const value=x=>x.type==='checkbox'?x.checked:x.value;
 const restore=(el,values)=>{for(const x of fields(el))if(Object.hasOwn(values,x.name)){if(x.type==='checkbox')x.checked=values[x.name];else x.value=values[x.name];}if(values.descriptionBlocks)renderDescriptionBlocks(values.descriptionBlocks);};
 let saved={};try{saved=JSON.parse(store.storage.getItem(key)||'{}')}catch{toast('Saved invoice customizations could not be read');}
 const top=f.querySelector(':scope > .field-grid');
 const split=(source,names,title)=>{const group=document.createElement('details');group.innerHTML='<summary>'+title+'</summary>';source.after(group);for(const name of names){const control=source.querySelector('[name="'+name+'"]');if(control)group.append(control.closest('.field'));}return group;};
 split(top,['billTo','billToAddress','billToPhone','billToEmail','billToTaxId'],'Client billing details');
 for(const details of [...f.querySelectorAll(':scope > details')]){const title=details.querySelector('summary').textContent;if(title==='Business & signature details'){split(details,['signatory'],'Authorized signature');split(details,['invoicePaymentInfo'],'Payment information');details.querySelector('summary').textContent='Company information';}if(title==='Notes & terms'){split(details,['terms'],'Terms & Conditions');details.querySelector('summary').textContent='Notes';}}

 const definitions=[[top,'Invoice information'],[f.querySelector('.manual-invoice-description'),'Item & Description'],...[...f.querySelectorAll(':scope > details')].map(el=>[el,el.querySelector('summary').textContent]),[f.querySelector('[name="additionalDetails"]')?.closest('.field'),'Additional details']];
 definitions.forEach(([el,title],i)=>{
 if(!el)return;
 // Financial amounts remain sourced from the ledger; descriptions are customizable.
 if(title==='Pricing & payment records'){el.querySelector('[data-apply-invoice-pricing]')?.remove();el.querySelector('[data-action]')?.remove();el.querySelectorAll('input').forEach(x=>x.readOnly=true);const hint=el.querySelector('.subtext');if(hint)hint.textContent='Amounts and balances follow the booking and recorded payments. Invoice customization never changes financial records.';return;}
 const section=document.createElement('section');section.className='invoice-edit-section';el.before(section);section.append(el);
 const baseline=Object.fromEntries(fields(el).map(x=>[x.name,value(x)]));if(title==='Item & Description')baseline.descriptionBlocks=[...el.querySelectorAll('textarea')].map(x=>x.value);
 const sectionId=title;
 if(saved[sectionId])restore(el,saved[sectionId]);
 const toolbar=document.createElement('div');toolbar.className='invoice-section-controls';toolbar.innerHTML='<strong>'+esc(title)+'</strong><div><button type="button" class="small" data-section-edit>Edit</button><button type="button" class="small" data-section-save hidden>Save</button><button type="button" class="small" data-section-reset>Reset</button></div><span class="subtext" role="status"></span>';section.prepend(toolbar);
 const lock=locked=>{el.querySelectorAll('input,textarea,select,button').forEach(x=>{if(x.type!=='hidden')x.disabled=locked;});toolbar.querySelector('[data-section-edit]').hidden=!locked;toolbar.querySelector('[data-section-save]').hidden=locked;section.classList.toggle('editing',!locked);};
 if(title==='Terms & Conditions'){el.open=true;const terms=el.querySelector('[name="terms"]');if(terms)terms.rows=10;lock(false);}else lock(true);
 toolbar.addEventListener('click',e=>{if(e.target.closest('[data-section-edit]')){lock(false);if(el.tagName==='DETAILS')el.open=true;el.querySelector('input:not([type="hidden"]),textarea,select')?.focus();}
 if(e.target.closest('[data-section-save]')){if(fields(el).some(x=>!x.checkValidity())){fields(el).find(x=>!x.checkValidity()).reportValidity();return;}const values=Object.fromEntries(fields(el).map(x=>[x.name,value(x)]));if(title==='Item & Description')values.descriptionBlocks=[...el.querySelectorAll('[data-description-block]')].map(x=>x.value);try{saved[sectionId]=values;store.storage.setItem(key,JSON.stringify(saved));lock(true);toolbar.querySelector('[role="status"]').textContent='Saved for this invoice draft';}catch(err){toast('Section could not be saved: '+err.message);}}
 if(e.target.closest('[data-section-reset]')){const next={...saved};delete next[sectionId];try{store.storage.setItem(key,JSON.stringify(next));saved=next;restore(el,baseline);lock(true);toolbar.querySelector('[role="status"]').textContent='Reset to original draft values';}catch(err){toast('Section could not be reset: '+err.message);}}
 readEditableInvoiceDraft();$('#invoice-preview-body').innerHTML=invoiceMarkup(currentInvoiceDraft);
 });
 });
 // Disabled controls are still included when reading the document draft.
 readEditableInvoiceDraft();$('#invoice-preview-body').innerHTML=invoiceMarkup(currentInvoiceDraft);
}

function invoiceSectionFormData(form){const clone=form.cloneNode(true);const originals=[...form.querySelectorAll('input,textarea,select')];[...clone.querySelectorAll('input,textarea,select')].forEach((x,i)=>{x.disabled=false;x.value=originals[i].value;if(x.type==='checkbox')x.checked=originals[i].checked;});return new FormData(clone);}

document.addEventListener('click',e=>{
 const button=e.target.closest('[data-save-invoice-payment-date]');if(!button)return;
 const form=$('#invoice-draft-form'),error=form.querySelector('[data-payment-date-error]');error.textContent='';
 try{
 const id=button.dataset.saveInvoicePaymentDate,input=[...form.querySelectorAll('[data-invoice-payment-date]')].find(x=>x.dataset.invoicePaymentDate===id);
 if(!input.value||invoicePaymentDate(input.value)==='Not recorded')throw Error('Choose a valid payment received date');
 const payment=store.data.payments.find(p=>p.id===id);if(!payment||payment.client!==currentInvoiceDraft.client)throw Error('Payment not found for this client');
 readEditableInvoiceDraft();
 const oldDate=payment.date,updated=store.editPayment(id,{...payment,date:input.value,sourceDateUnknown:false});
 currentInvoiceDraft.payments=currentInvoiceDraft.payments.map(p=>p.id===id?structuredClone(updated):p);
 if(currentInvoiceDraft.paymentId===id)currentInvoiceDraft.payment=structuredClone(updated);
 if(currentInvoiceDraft.date===oldDate||currentInvoiceDraft.paymentId===id){currentInvoiceDraft.date=updated.date;form.elements.date.value=updated.date;}
 const index=currentInvoiceDraft.payments.findIndex(p=>p.id===id),label=form.elements['paymentLabel-'+index];
 if(label){label.value=invoicePaymentLabel(updated,label.value);currentInvoiceDraft.paymentLabels[id]=label.value;}
 $('#invoice-preview-body').innerHTML=invoiceMarkup(currentInvoiceDraft);toast('Payment date saved. Preview and new PDF updated.');
 }catch(err){error.textContent=err.message;}
});
